function normalizeStoredTicketItems(value = []) {
  const source = Array.isArray(value) ? value : [];
  const before = JSON.stringify(source.map(item => ({
    store:item?.store||'', name:item?.name||'', quantity:num(item?.quantity)||1,
    price:num(item?.price), unitPrice:num(item?.unitPrice), date:item?.date||''
  })));
  const consolidated = consolidateStoredTicketItems(source).map(item => ({
    ...item,
    id: item.id || uid('ocr'),
    quantity: Math.max(.01, num(item.quantity) || 1),
    price: Number(num(item.price).toFixed(2)),
    unitPrice: Number((num(item.unitPrice) || (num(item.price) / Math.max(.01, num(item.quantity) || 1))).toFixed(2))
  }));
  const after = JSON.stringify(consolidated.map(item => ({
    store:item.store||'', name:item.name||'', quantity:item.quantity,
    price:item.price, unitPrice:item.unitPrice, date:item.date||''
  })));
  if (before !== after || source.some(item=>!Array.isArray(item?.ticketBreakdown))) pendingTicketItemMigration = true;
  return consolidated;
}

function tripMenuDates(settings={}) {
  const start=String(settings.departureDateTime||"").slice(0,10),end=String(settings.returnDateTime||"").slice(0,10);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||start>end)return [];
  const out=[];let cursor=new Date(`${start}T12:00:00`),limit=new Date(`${end}T12:00:00`),guard=0;
  while(cursor<=limit&&guard++<62){out.push(cursor.toISOString().slice(0,10));cursor.setDate(cursor.getDate()+1);}
  return out;
}
function normalizeMenuDays(menu,settings){
  const existing=Array.isArray(menu?.days)?menu.days:[],byDate=new Map(existing.map(day=>[String(day.date||""),day]));
  const dates=tripMenuDates(settings);
  const normalizeDay=(date,day={})=>({date,breakfast:day.breakfast||"",lunch:day.lunch||"",dinner:day.dinner||"",notes:day.notes||"",showBreakfast:day.showBreakfast!==false,showLunch:day.showLunch!==false,showDinner:day.showDinner!==false});
  if(!dates.length)return existing.map(day=>normalizeDay(String(day.date||""),day));
  const next=dates.map((date,index)=>{
    const direct=byDate.get(date);
    if(direct)return normalizeDay(date,direct);
    const fallback=existing[index]||{};
    return normalizeDay(date,fallback);
  });
  if(JSON.stringify(next)!==JSON.stringify(existing))pendingMenuMigration=true;
  return next;
}
function syncMenuDaysWithTripDates(){
  state.data.menu=state.data.menu||{days:[]};state.data.menu.days=normalizeMenuDays(state.data.menu,state.data.settings);
}
function normalizeSuitcaseGroup(group={},index=0){
  const subgroups=(Array.isArray(group?.subgroups)?group.subgroups:[]).map((subgroup,subIndex)=>(
    {
      id:String(subgroup?.id||'').trim()||`suitcase-subgroup-${index+1}-${subIndex+1}`,
      name:String(subgroup?.name||`Subgrupo ${subIndex+1}`).trim()||`Subgrupo ${subIndex+1}`,
      icon:String(subgroup?.icon||'').trim(),
      iconUrl:String(subgroup?.iconUrl||'').trim(),
      color:String(subgroup?.color||group?.color||'#4da3ff').trim()||'#4da3ff',
      textColor:String(subgroup?.textColor||group?.textColor||'#ffffff').trim()||'#ffffff'
    }
  ));
  const allowed=new Set(subgroups.map(subgroup=>subgroup.id));
  const items=(Array.isArray(group?.items)?group.items:[]).map((item,itemIndex)=>({
    ...item,
    id:String(item?.id||'').trim()||`suitcase-item-${index+1}-${itemIndex+1}`,
    name:String(item?.name||'').trim(),
    checked:Boolean(item?.checked),
    subgroupId:allowed.has(String(item?.subgroupId||''))?String(item.subgroupId):''
  }));
  return {...group,textColor:String(group?.textColor||'#ffffff').trim()||'#ffffff',subgroups,items};
}
function normalizeSuitcaseCollection(source=[],fallback=[]){
  const groups=Array.isArray(source)?source:(Array.isArray(fallback)?fallback:[]);
  return groups.map((group,index)=>normalizeSuitcaseGroup(group,index));
}

function syncBudgetBusHeaderVisual(data={},sourceBus=null){
  const groups=Array.isArray(data?.budget?.groups)?data.budget.groups:[];
  const group=groups.find(item=>item?.id==='g-bus');
  const buses=Array.isArray(data?.cover?.buses)?data.cover.buses:[];
  const bus=sourceBus||buses.find(item=>item&&item.visible!==false)||buses[0];
  if(!group||!bus)return false;
  const next={
    gradient1:String(bus.gradient1||bus.color||group.gradient1||group.color||'#173f53'),
    gradient2:String(bus.gradient2||bus.color||group.gradient2||group.color||'#2d7895'),
    textColor:String(bus.textColor||group.textColor||'#ffffff')
  };
  let changed=false;
  for(const [key,value] of Object.entries(next)){
    if(String(group[key]||'')!==value){group[key]=value;changed=true;}
  }
  return changed;
}
// v2.4.10 · Cordial: resúmenes e históricos usan Reserva Online sin gastos, no Prepago.
// v2.4.9 · Memoria persistente de iconos por concepto/comercio.
function budgetConceptIconKey(value=''){
  return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
}
function normalizeBudgetConceptIconMemory(value={}){
  const out={};
  if(!value||typeof value!=='object'||Array.isArray(value))return out;
  for(const [rawKey,raw] of Object.entries(value)){
    const key=budgetConceptIconKey(raw?.name||rawKey),icon=String(raw?.icon||'').trim(),iconUrl=String(raw?.iconUrl||'').trim();
    if(!key||(!icon&&!iconUrl))continue;
    out[key]={name:String(raw?.name||rawKey).trim()||rawKey,icon,iconUrl};
  }
  return out;
}
function mergedBudgetConceptIconMemory(data={}){
  const out={};
  const put=(name,value={})=>{
    const label=String(name||'').trim(),key=budgetConceptIconKey(label),icon=String(value?.icon||'').trim(),iconUrl=String(value?.iconUrl||'').trim();
    if(!key||(!icon&&!iconUrl))return;
    out[key]={name:label||String(value?.name||'').trim()||key,icon,iconUrl};
  };
  // Histórico: del más antiguo al más reciente para que el último icono usado gane.
  for(const archive of [...(data.history?.archives||[])].reverse()){
    for(const group of archive?.budget?.groups||[])for(const item of group?.items||[])put(item?.name,item);
    for(const item of archive?.purchases?.extras||[])put(item?.name,item);
    for(const item of archive?.purchases?.otherExpenses||[])put(item?.name,item);
  }
  // La memoria ya guardada prevalece sobre históricos antiguos.
  for(const record of Object.values(normalizeBudgetConceptIconMemory(data.budget?.conceptIconMemory||{})))put(record.name,record);
  // Los datos del viaje activo son la referencia más reciente.
  for(const group of data.budget?.groups||[])for(const item of group?.items||[])put(item?.name,item);
  for(const item of data.purchases?.extras||[])put(item?.name,item);
  for(const item of data.purchases?.otherExpenses||[])put(item?.name,item);
  return out;
}

