      cordial: { ...base.trackers.cordial, title:"Cordial Santa Águeda", titleIcon:TRACKER_DEFAULT_ICONS.cordial, titleIconUrl:"", color:"#35a5d6", gradient1:"#113b58", gradient2:"#166b91", textColor:"#ffffff", lastError:"", monitorStatus:"pending", ...(incoming.trackers?.cordial || {}) },
