  return `<article class="card stage-reservation-card" style="--stage-card-a:${esc(item?.gradient1|| (hotel?'#29313c':'#173d20'))};--stage-card-b:${esc(item?.gradient2||(hotel?'#626d7b':'#478034'))}"><div class="stage-card-head"><div><small>${esc(stageTitle(stage,index))} · ${hotel?'Hotel':'Coche'}</small><h3>${esc(title)}</h3></div>${controls}</div><div class="stage-card-body">${image}<p>${esc(desc.filter(Boolean).join(' · '))}</p>${first?`<small class="muted">${hotel?'Ficha histórica de alojamiento':'Seguimiento AutoReisen'} · edición de la primera etapa</small>`:''}${!first&&price?`<strong>${formatMoney(price)} · ${item.status==='paid'?'Pagado':'Pendiente'}</strong>`:''}${!first&&checkedPrice?`<small>Último precio: ${formatMoney(checkedPrice)}${price?` · ${difference>=0?'+':''}${formatMoney(difference)} respecto a reserva`:''}</small>`:''}<div class="page-actions">${safeLink(url,'Web','🌐')}${safeLink(mapsDirectionsUrl(address,hotel?item?.mapsUrl:undefined),'Ruta','📍')}${stageCheck}${files}</div></div></article>`;
