 return `<div class="stage-purchases-grid">${stages.map((stage,i)=>{const items=records.filter(r=>stageIdForRecord(r)===stage.id),total=sum(items.map(r=>r.amount));return `<article class="card stage-summary-card"><div><span class="header-kicker">🛒 ${esc(stageTitle(stage,i))}</span><h3>${formatMoney(total)}</h3><p class="muted">${items.length} compra${items.length===1?'':'s'} registradas</p></div>${canEdit()?`<button class="btn secondary small" data-stage-add-purchase="${esc(stage.id)}">＋ Compra</button>`:''}</article>`;}).join('')}</div>`;
