function editTripStage(index){
  const stage=state.data.stages.items[index];if(!stage)return;
  openForm({title:`Configurar ${stage.label||`Semana ${index+1}`}`,fields:[
    {name:'label',label:'Nombre de la etapa',required:true},{name:'island',label:'Isla / destino',full:true},
    {name:'start',label:'Primer día',type:'date'},{name:'end',label:'Último día',type:'date'},
    {name:'weatherPlace',label:'Localidad del tiempo',full:true},{name:'weatherLatitude',label:'Latitud',type:'number',step:'any'},{name:'weatherLongitude',label:'Longitud',type:'number',step:'any'}
  ],values:stage,onSubmit:async values=>{
    if(values.start&&values.end&&values.end<values.start)throw new Error('La fecha de fin no puede ser anterior al inicio.');
    const other=state.data.stages.items[index===0?1:0]||{};
    if(index===1&&other.end&&values.start&&values.start<other.end)throw new Error('La segunda semana no puede empezar antes de que termine la primera.');
    if(index===0&&other.start&&values.end&&values.end>other.start)throw new Error('La primera semana debe terminar antes del comienzo de la segunda.');
    Object.assign(stage,values);delete state.stageWeather?.[stage.id];
    const settings=state.data.settings;
    if(index===0){
      if(values.weatherPlace){settings.weatherPlace=values.weatherPlace;settings.weatherLatitude=values.weatherLatitude||'';settings.weatherLongitude=values.weatherLongitude||'';state.weather=null;}
      if(values.start){settings.departureDateTime=`${values.start}${String(settings.departureDateTime||'').match(/T.*/)?.[0]||'T12:00:00'}`;settings.year=Number(values.start.slice(0,4))||settings.year;}
    }else if(values.end){settings.returnDateTime=`${values.end}${String(settings.returnDateTime||'').match(/T.*/)?.[0]||'T12:00:00'}`;}
    const stage1=state.data.stages.items[0]||{},stage2=state.data.stages.items[1]||{};
    if(stage1.island&&stage2.island)settings.destination=`${stage1.island} · ${stage2.island}`;
    syncMenuDaysWithTripDates();
    const saved=await Promise.all([saveSection('stages'),saveSection('settings'),saveSection('menu')]);
    if(saved.includes(false))throw new Error('No se pudieron guardar todas las fechas.');
    render();if(index===0&&values.weatherPlace)void refreshWeather();
  }});
}
