function airportCodeFromText(value=''){return String(value||'').toUpperCase().match(/\b([A-Z]{3})\b/)?.[1]||'';}
function flightOpsConfigFromState(){return {enabled:true,flights:(state.data.cover.flights||[]).map((f,index)=>({id:String(f.id||`flight-${index+1}`),number:String(f.number||'').trim(),date:String(f.date||f.departure||'').slice(0,10),departure:String(f.departure||''),arrival:String(f.arrival||''),origin:airportCodeFromText(f.from),destination:airportCodeFromText(f.to),from:String(f.from||''),to:String(f.to||''),operationalHints:{...(f.operationalHints||{})}})).filter(f=>f.number&&f.departure&&f.origin&&f.destination)};}
function flightOpsMonitoringWindow(flight={},now=Date.now()){
  const raw=String(flight.departure||flight.date||'').trim();
  const dep=Date.parse(raw.includes('T')?raw:`${String(flight.date||raw).slice(0,10)}T12:00:00`);
  if(!Number.isFinite(dep))return false;
  const delta=dep-now;
  return delta<=14*86400000&&delta>=-3*86400000;
}
function flightOpsForFlight(flight={},index=0){
  // Aena solo tiene sentido cerca de la salida. Esta barrera evita que un VY3272
  // de otro año/día se cuele por coincidir número y ruta en la API de dos días.
  if(!flightOpsMonitoringWindow(flight))return null;
  const results=state.flightOps?.result?.flights||[];
  const number=String(flight.number||'').replace(/\s+/g,'').toUpperCase();
  const date=String(flight.date||flight.departure||'').slice(0,10);
  const rowNumber=x=>String(x?.number||'').replace(/\s+/g,'').toUpperCase();
  const rowDate=x=>String(x?.date||x?.departure||'').slice(0,10);
  if(!number||!date)return null;
  return results.find(x=>rowNumber(x)===number&&rowDate(x)===date)||null;
}
function flightOpsFreshnessText(value=''){const stamp=Date.parse(value);if(!Number.isFinite(stamp))return '';const minutes=Math.max(0,Math.round((Date.now()-stamp)/60000));if(minutes<2)return 'ahora';if(minutes<60)return `hace ${minutes} min`;const hours=Math.round(minutes/60);return `hace ${hours} h`;}
function flightOpsStatusMarkup(flight,index){const ops=flightOpsForFlight(flight,index);if(!ops)return `<div class="flight-ops-strip is-pending is-compact"><div class="flight-ops-status"><span class="flight-ops-dot"></span><strong>Información operativa pendiente</strong><small>Aena · sin datos confirmados</small></div><button type="button" class="mini-btn flight-ops-refresh" data-flightops-refresh title="Actualizar estado del vuelo" aria-label="Actualizar estado del vuelo">↻</button></div>`;const cleanValue=value=>{const v=String(value??'').trim();return !v||/^(?:null|undefined|n\/a|na|—|-)$/i.test(v)?'':v;};const verified=ops.identityVerified===true,rawStatus=cleanValue(ops.status),terminal=cleanValue(ops.terminal),gate=cleanValue(ops.gate),checkInCounters=cleanValue(ops.checkInCounters),baggageBelt=cleanValue(ops.baggageBelt),boardingStart=cleanValue(ops.boardingStart),boardingClose=cleanValue(ops.boardingClose);const boardingLabel=boardingStart?`${boardingStart}${boardingClose?`–${boardingClose}`:''}`:'';const hasRealDetails=Boolean(terminal||gate||checkInCounters||baggageBelt||boardingStart||boardingClose);const status=(verified&&ops.statusVerified===true&&rawStatus)?rawStatus:(verified&&hasRealDetails?'Datos operativos disponibles':'Información operativa pendiente'),tone=!verified?'is-pending':/cancel/i.test(status)?'is-danger':/retras|delay/i.test(status)?'is-warning':hasRealDetails||/hora|boarding|embar|aterr|despeg/i.test(status)?'is-good':'',sources=[...(ops.sources||[])],liveAena=sources.some(x=>x?.name==='Aena'&&x?.identityVerified===true&&x?.mode!=='snapshot'),snapshotSource=sources.find(x=>x?.mode==='snapshot'&&x?.identityVerified===true),fresh=flightOpsFreshnessText(state.flightOps?.result?.checkedAt||'');const detail=(label,value,cls='')=>`<span class="flight-ops-detail ${cls}"><small>${label}</small><b>${verified&&value?esc(value):'—'}</b></span>`;let subtitle='Aena · sin datos confirmados';if(liveAena)subtitle=`Aena directo · dato real${fresh?` · ${fresh}`:''}`;else if(snapshotSource||ops.fallbackSnapshot)subtitle=`${snapshotSource?.name||ops.sourceLabel||'Última info confirmada'} · respaldo, no en vivo`;else if(verified)subtitle=`${ops.sourceLabel||'Aena'}${fresh?` · ${fresh}`:''}`;if(!hasRealDetails&&(!rawStatus||/información operativa pendiente/i.test(status))){return `<div class="flight-ops-strip is-pending is-compact"><div class="flight-ops-status"><span class="flight-ops-dot"></span><strong>Sin datos operativos todavía</strong><small>${esc(subtitle)}</small></div><button type="button" class="mini-btn flight-ops-refresh" data-flightops-refresh title="Actualizar estado del vuelo" aria-label="Actualizar estado del vuelo">↻</button></div>`;}return `<div class="flight-ops-strip ${tone}"><div class="flight-ops-status"><span class="flight-ops-dot"></span><strong>${esc(status)}</strong><small>${esc(subtitle)}</small></div><div class="flight-ops-details">${detail('Terminal',terminal)}${detail('Puerta',gate,'is-gate')}${detail('Facturación',checkInCounters)}${detail('Embarque',boardingLabel)}${detail('Cinta',baggageBelt)}</div><button type="button" class="mini-btn flight-ops-refresh" data-flightops-refresh title="Actualizar estado del vuelo" aria-label="Actualizar estado del vuelo">↻</button></div>`;}
async function loadFlightOps({silent=true}={}){if(state.flightOps.syncing)return state.flightOps.result;state.flightOps.syncing=true;try{const data=await callIntegrationWorker({action:'flightops-read'},{timeoutMs:10000});state.flightOps.result=data.result||null;state.flightOps.lastError=data.lastError||null;state.flightOps.fetchedAt=Date.now();if(!silent)toast(data.result?'Estado de vuelos actualizado.':'Aún no hay información operativa guardada.');return state.flightOps.result;}catch(error){if(!silent)toast(error.message,'error');return null;}finally{state.flightOps.syncing=false;}}
async function loadFlightOpsLive({silent=true}={}){const config=flightOpsConfigFromState();if(!config.flights.length)return null;const data=await callIntegrationWorker({action:'flightops-live',config},{timeoutMs:18000});if(data?.result){state.flightOps.result=data.result;state.flightOps.lastError=null;state.flightOps.fetchedAt=Date.now();if(!silent)toast(data.result.flights?.some(f=>f.hasOperationalData)?'Aena actualizado al momento.':'Aena todavía no publica datos operativos para ese vuelo.');return data.result;}return null;}
