async function refreshFlightOpsNow(){const buttons=$$('[data-flightops-refresh]');buttons.forEach(b=>b.disabled=true);try{let live=null;try{live=await loadFlightOpsLive({silent:false});}catch(error){console.warn('Aena directo:',error);toast(`Aena directo: ${error.message}. Lanzo respaldo.`, 'warning');}if(state.activeTab==='cover')render();const hasData=Boolean(live?.flights?.some(f=>f?.hasOperationalData));if(roleCanEdit())ensureFlightOpsAutomation({runWorkflow:!hasData,silent:true}).catch(()=>{});if(!hasData)setTimeout(async()=>{await loadFlightOps({silent:true});if(state.activeTab==='cover')render();},35000);}finally{buttons.forEach(b=>b.disabled=false);}}
