    {url:h.bookingReviewsUrl||'https://www.booking.com/hotel/es/apartamentos-dunas-club.es.html',label:h.bookingReviewsLabel||defaults.bookingReviewsLabel,color:h.bookingReviewsColor||defaults.bookingReviewsColor,icon:brandIconMarkup('booking'),service:'booking'}
