function trackerBudgetPreviewImage(kind) {
  if(kind==='autoreisen'){
    const tracker=state.data.trackers?.autoreisen||{};
    const url=isImageSource(tracker.manualImageUrl)?String(tracker.manualImageUrl):isImageSource(tracker.imageUrl)?String(tracker.imageUrl):'';
    return url?{url,title:tracker.model||'Vehículo AutoReisen'}:null;
  }
  if(kind==='cordial'){
    const tracker=state.data.trackers?.cordial||{};
    const targetRoom=tracker.targetRoom||'Classic Duplex';
    const meta=cordialRoomMeta(tracker,targetRoom)||{};
    const workerImage=isImageSource(meta.imageUrl)?String(meta.imageUrl):'';
    if(workerImage)return {url:workerImage,title:targetRoom};
    const lodging=state.data.cover?.lodging||{};
    const fallback=isImageSource(lodging.imageUrl)?String(lodging.imageUrl):'';
    return fallback?{url:fallback,title:lodging.name||'Alojamiento'}:null;
  }
  return null;
}
function budgetPreviewAsset(group,item) {
  const text=`${group?.id||''} ${group?.name||''} ${item?.name||''} ${item?.detail||''}`.toLocaleLowerCase('es');
  if(/autoreisen|alquiler\s*coche|rva\d+/i.test(text)){
    const preview=trackerBudgetPreviewImage('autoreisen');
    return preview?{...preview,kind:'autoreisen'}:null;
  }
  if(/cordial|santa\s*águeda|santa\s*agueda|rol\d+/i.test(text)){
    const preview=trackerBudgetPreviewImage('cordial');
    return preview?{...preview,kind:'cordial'}:null;
  }
  return null;
}

function budgetAirportCode(value=''){
  const source=String(value||'').toUpperCase();
  return source.match(/\(([A-Z]{3})\)/)?.[1]||source.match(/\b([A-Z]{3})\b/)?.[1]||'';
}
function budgetFlightForItem(item){
  const flights=state.data.cover.flights||[];
  if(!flights.length||!item)return null;
  const itemKey=String(item.name||'').toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'');
  const byRoute=flights.find(f=>{
    const from=budgetAirportCode(f.from),to=budgetAirportCode(f.to);
    return from&&to&&(itemKey===`${from}-${to}`||itemKey.includes(`${from}-${to}`));
  });
  if(byRoute)return byRoute;
  const number=String(item.detail||'').toUpperCase().match(/VY\s*\d{3,5}/)?.[0]?.replace(/\s+/g,'');
  if(number)return flights.find(f=>String(f.number||'').toUpperCase().replace(/\s+/g,'')===number)||null;
  return null;
}

function poolPanelConfig(){
  const defaults=SEED_DATA.settings.poolPanel||{};
  const cfg=state.data?.settings?.poolPanel||{};
  const merged={...defaults,...cfg,webcams:{...(defaults.webcams||{}),...(cfg.webcams||{})},poolStyles:{...(defaults.poolStyles||{}),...(cfg.poolStyles||{})}};
  // v2.3.43 · Se retira la webcam El Perchel: eliminar también configuraciones antiguas ya guardadas en Firebase/local.
  merged.webcams=Object.fromEntries(Object.entries(merged.webcams||{}).filter(([id])=>id==='santa-agueda'));
  merged.sectionOrder=(Array.isArray(merged.sectionOrder)?merged.sectionOrder:['webcams','pools','temperatureChart','source']).filter(id=>id!=='spa');
  merged.hiddenSections=(Array.isArray(merged.hiddenSections)?merged.hiddenSections:[]).filter(id=>id!=='spa');
  return merged;
}
function poolConfigKey(name=''){return String(name||'Piscina').trim().toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'piscina';}
function orderedPoolList(pools=[]){const cfg=poolPanelConfig(),order=cfg.poolOrder||[];return [...pools].sort((a,b)=>{const ai=order.indexOf(poolConfigKey(a?.name)),bi=order.indexOf(poolConfigKey(b?.name));return (ai<0?999:ai)-(bi<0?999:bi);});}
function poolStyleFor(pool={}){const cfg=poolPanelConfig(),specific=cfg.poolStyles?.[poolConfigKey(pool.name)]||{};return {background:specific.background||cfg.cardBackground||'#171a20',border:specific.border||cfg.cardBorder||'#343b49',temperatureBackground:specific.temperatureBackground||cfg.temperatureBackground||'#10263a',temperatureText:specific.temperatureText||cfg.temperatureText||'#ffffff',metricBackground:specific.metricBackground||cfg.metricBackground||'#20242d'};}
function poolSectionVisible(id){return !(poolPanelConfig().hiddenSections||[]).includes(id);}
function poolPayloadTimestamp(payload={},fallback=''){
  const candidates=[payload?.clientFetchedAt,payload?.checkedAt,payload?.receivedAt,payload?.fetchedAt,payload?.updatedAt,fallback]
    .map(value=>value?new Date(value):null)
    .filter(date=>date&&Number.isFinite(date.getTime()));
  if(!candidates.length)return null;
  return candidates.reduce((latest,date)=>date.getTime()>latest.getTime()?date:latest,candidates[0]);
}
function poolMeasurementTimestamp(measurement={},fallback=''){
  const raw=[measurement.date,measurement.time].filter(Boolean).join('T');
  const parsed=raw?new Date(raw):null;
  if(parsed&&Number.isFinite(parsed.getTime()))return parsed;
  const fallbackDate=fallback?new Date(fallback):null;
  return fallbackDate&&Number.isFinite(fallbackDate.getTime())?fallbackDate:null;
}
function poolMeasurementTemperatureForChart(measurement={}){
  const direct=measurement?.temperature;
  if(direct!==null&&direct!==undefined&&direct!==''){
    const n=num(String(direct).replace(',','.'));if(Number.isFinite(n)&&n>-5&&n<60)return n;
  }
  for(const metric of measurement?.metrics||[]){
    if(!/temperatura|temperature|temp\.?\b/i.test(String(metric?.label||'')))continue;
    const hit=String(metric?.value??'').replace(',','.').match(/-?\d+(?:\.\d+)?/),n=hit?Number(hit[0]):NaN;
    if(Number.isFinite(n)&&n>-5&&n<60)return n;
  }
  return null;
}
function poolTemperatureSeries(poolName,payload=state.poolMeasurements){
  const key=String(poolName||'').trim().toLocaleLowerCase('es'),points=[];
  const add=(time,temp,label='')=>{const n=num(temp);if(!Number.isFinite(n)||n<-5||n>60)return;const date=time instanceof Date?time:new Date(time);if(!Number.isFinite(date.getTime()))return;points.push({time:date,temp:n,label});};
  for(const snap of payload?.history||[]){
    const pool=(snap.pools||[]).find(p=>String(p.name||'').trim().toLocaleLowerCase('es')===key);if(!pool)continue;
    const latest=poolLatestMeasurement(pool),temp=poolTemperatureValue(pool,latest);
    if(temp!==null&&temp!==undefined){const snapTime=poolPayloadTimestamp(snap);if(snapTime)add(snapTime,temp,'Histórico');}
  }
  const current=(payload?.pools||[]).find(p=>String(p.name||'').trim().toLocaleLowerCase('es')===key);
  for(const m of poolNormalizedMeasurements(current||{})){
    const temp=poolMeasurementTemperatureForChart(m);if(temp===null||temp===undefined)continue;
    const ts=poolMeasurementTimestamp(m,poolPayloadTimestamp(payload)?.toISOString()||'');if(ts)add(ts,temp,m.measurement||'Medición');
  }
  // La ficha actual y el gráfico deben compartir siempre el mismo dato. Aunque el histórico del Worker
  // todavía no haya guardado la lectura, inyectamos el valor que la app acaba de consultar como último punto.
  if(current){
    const temp=poolTemperatureValue(current,poolLatestMeasurement(current));
    const currentTime=poolPayloadTimestamp(payload,payload?.clientFetchedAt||new Date().toISOString());
    if(temp!==null&&temp!==undefined&&currentTime)add(currentTime,temp,'Actual');
  }
  const dedup=new Map();for(const point of points.sort((a,b)=>a.time-b.time)){const k=`${point.time.getTime()}|${point.temp}`;dedup.set(k,point);}return [...dedup.values()].slice(-80);
}
function renderPoolTemperatureChart(payload=state.poolMeasurements){
  const pools=payload?.pools||[];if(!pools.length)return '<div class="pool-chart-empty">Todavía no hay mediciones para dibujar el gráfico.</div>';
  const series=pools.map((pool,index)=>({name:pool.name,index,points:poolTemperatureSeries(pool.name,payload)})).filter(s=>s.points.length);
  const all=series.flatMap(s=>s.points);if(all.length<2)return '<div class="pool-chart-empty">El histórico de temperatura se irá formando automáticamente con las siguientes mediciones.</div>';
  const temps=all.map(p=>p.temp),min=Math.floor(Math.min(...temps)-1),max=Math.ceil(Math.max(...temps)+1),span=Math.max(1,max-min);
  const times=all.map(p=>p.time.getTime()),tMin=Math.min(...times),tMax=Math.max(...times),tSpan=Math.max(1,tMax-tMin);
  const W=720,H=250,left=44,right=18,top=18,bottom=38,plotW=W-left-right,plotH=H-top-bottom;
  const x=t=>left+((t-tMin)/tSpan)*plotW,y=v=>top+((max-v)/span)*plotH;
  const palette=['#4da3ff','#f6d51f','#4bd1a0','#ff7f66','#b58cff','#ffb455','#55d8ff'];
  const grid=[0,.25,.5,.75,1].map(f=>{const val=max-span*f,yy=top+plotH*f;return `<g><line x1="${left}" y1="${yy.toFixed(1)}" x2="${W-right}" y2="${yy.toFixed(1)}" class="pool-chart-grid"/><text x="${left-8}" y="${(yy+4).toFixed(1)}" text-anchor="end" class="pool-chart-axis">${val.toFixed(0)}°</text></g>`}).join('');
  const lines=series.map((s,i)=>{const color=palette[i%palette.length],pts=s.points.map(p=>`${x(p.time.getTime()).toFixed(1)},${y(p.temp).toFixed(1)}`).join(' ');const dots=s.points.map(p=>{const text=`${s.name} · ${p.temp.toLocaleString('es-ES',{maximumFractionDigits:1})} °C · ${p.time.toLocaleString('es-ES',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}`;return `<circle cx="${x(p.time.getTime()).toFixed(1)}" cy="${y(p.temp).toFixed(1)}" r="4" fill="${color}" class="tracker-chart-hover-point" tabindex="0" data-tracker-chart-tooltip="${esc(text)}"><title>${esc(text)}</title></circle>`;}).join('');return `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${dots}`}).join('');
  const start=new Date(tMin).toLocaleString('es-ES',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}),end=new Date(tMax).toLocaleString('es-ES',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
  const legend=series.map((s,i)=>`<span><i style="--pool-series:${palette[i%palette.length]}"></i>${esc(s.name)}</span>`).join('');
  return `<div class="pool-chart-wrap"><svg class="pool-temp-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución de temperatura de las piscinas">${grid}${lines}<text x="${left}" y="${H-10}" class="pool-chart-axis">${esc(start)}</text><text x="${W-right}" y="${H-10}" text-anchor="end" class="pool-chart-axis">${esc(end)}</text></svg><div class="pool-chart-legend">${legend}</div></div>`;
}
function poolMetricDisplayLabel(label=''){
  const text=String(label||'').trim();
  if(/turbidez|turbidity/i.test(text))return 'Turbidez (UNF)';
  if(/recirculaci[oó]n|recirculation/i.test(text))return 'Índice de recirculación (h)';
  return text;
}
function poolMetricClass(label=''){
  const text=String(label).toLocaleLowerCase('es');if(/temperatura|temperature|temp\.?\b/.test(text))return 'is-temperature';if(/\bph\b/.test(text))return 'is-ph';if(/cloro|chlor/.test(text))return 'is-chlorine';if(/recirculaci[oó]n|recirculation/.test(text))return 'is-recirculation';return '';
}
function poolMetricNumber(value=''){
  const hit=String(value??'').replace(',','.').match(/-?\d+(?:\.\d+)?/);return hit?Number(hit[0]):NaN;
}
function poolNormalizedMeasurements(pool={}){
  const source=(Array.isArray(pool.measurements)&&pool.measurements.length)?pool.measurements:(pool.latest?[pool.latest]:[]);
  const measurements=source.map(m=>({...m,metrics:(Array.isArray(m?.metrics)?m.metrics:[]).map(metric=>({...metric}))}));
  const latest=measurements.find(m=>/última|ultima|last/i.test(String(m?.measurement||'')))||measurements[0]||null;
  const latestTurbidity=(latest?.metrics||[]).find(metric=>/turbidez|turbidity/i.test(String(metric?.label||'')));
  const latestTurbidityValue=poolMetricNumber(latestTurbidity?.value);
  for(const measurement of measurements){
    if(/última|ultima|last/i.test(String(measurement?.measurement||'')))continue;
    const metrics=measurement.metrics||[];
    if(metrics.some(metric=>/recirculaci[oó]n|recirculation/i.test(String(metric?.label||''))))continue;
    if(metrics.length!==1)continue;
    const metric=metrics[0];
    if(!/turbidez|turbidity/i.test(String(metric?.label||'')))continue;
    const value=poolMetricNumber(metric?.value);
    if(Number.isFinite(value)&&Number.isInteger(value)&&value>=1&&value<=24&&Number.isFinite(latestTurbidityValue)&&latestTurbidityValue<1){metric.label='Índice de recirculación (h)';}
  }
  return measurements;
}
function poolLatestMeasurement(pool={}){
  const measurements=poolNormalizedMeasurements(pool);
  return measurements.find(m=>/última|ultima|last/i.test(String(m?.measurement||'')))||measurements[0]||{};
}
function poolHighlightedMetrics(pool={},latest=poolLatestMeasurement(pool)){
  const metrics=(latest?.metrics||[]).filter(m=>!(/fecha|date|hora|time/i.test(String(m?.label||'')))).map(m=>({...m}));
  const seen=new Set(metrics.map(m=>poolMetricDisplayLabel(m.label).toLocaleLowerCase('es')));
  for(const measurement of poolNormalizedMeasurements(pool)){
    for(const metric of measurement.metrics||[]){
      if(!/recirculaci[oó]n|recirculation/i.test(String(metric?.label||'')))continue;
      const key=poolMetricDisplayLabel(metric.label).toLocaleLowerCase('es');
      if(!seen.has(key)){metrics.push({...metric});seen.add(key);}
    }
  }
  return metrics.slice(0,6);
}
function poolTemperatureValue(pool={},latest=poolLatestMeasurement(pool)){
  const direct=[pool.temperature,latest?.temperature].find(v=>v!==null&&v!==undefined&&v!=='');
  if(direct!==undefined){const n=Number(String(direct).replace(',','.'));if(Number.isFinite(n)&&n>-5&&n<60)return n;}
  const metrics=Array.isArray(latest?.metrics)?latest.metrics:[];
  for(const metric of metrics){if(!/temperatura|temperature|temp\.?\b/i.test(String(metric?.label||'')))continue;const hit=String(metric?.value??'').replace(',','.').match(/-?\d+(?:\.\d+)?/);const n=hit?Number(hit[0]):NaN;if(Number.isFinite(n)&&n>-5&&n<60)return n;}
  return null;
}
function renderPoolMeasurementDetails(pool){
  const measurements=poolNormalizedMeasurements(pool);
  if(!measurements.length)return '<div class="empty">Sin controles detallados.</div>';
  return measurements.map((m,index)=>{const when=[m.date?formatDate(m.date,{day:'2-digit',month:'short'}):'',m.time||''].filter(Boolean).join(' · ');const rows=(m.metrics||[]).map(metric=>`<div class="pool-metric-row ${poolMetricClass(metric.label)}"><span>${esc(poolMetricDisplayLabel(metric.label))}</span><strong>${esc(metric.value)}</strong></div>`).join('');return `<section class="pool-measurement-set"><div class="pool-measurement-head"><strong>${esc(m.measurement||`Medición ${index+1}`)}</strong>${when?`<small>${esc(when)}</small>`:''}</div><div class="pool-metric-grid">${rows||'<span class="muted">Sin parámetros.</span>'}</div></section>`}).join('');
}
function renderPoolCard(pool){
  const latest=poolLatestMeasurement(pool),temperature=poolTemperatureValue(pool,latest),style=poolStyleFor(pool);
  const currentMetrics=poolHighlightedMetrics(pool,latest);
  const when=[latest.date?formatDate(latest.date,{day:'2-digit',month:'short'}):'',latest.time||''].filter(Boolean).join(' · ');
  return `<article class="pool-live-card" style="--pool-card-bg:${esc(style.background)};--pool-card-border:${esc(style.border)};--pool-temp-bg:${esc(style.temperatureBackground)};--pool-temp-text:${esc(style.temperatureText)};--pool-metric-bg:${esc(style.metricBackground)}"><div class="pool-live-head"><div><span class="pool-live-kicker">${esc(latest.measurement||'Última medición')}</span><h4>${esc(pool.name||'Piscina')}</h4>${when?`<small>${esc(when)}</small>`:''}</div><div class="pool-temperature ${temperature===null||temperature===undefined?'is-empty':''}"><span>${temperature===null||temperature===undefined?'—':esc(Number(temperature).toLocaleString('es-ES',{maximumFractionDigits:1}))}</span><small>°C</small></div></div><div class="pool-live-metrics">${currentMetrics.map(m=>`<div class="pool-metric-chip ${poolMetricClass(m.label)}"><small>${esc(poolMetricDisplayLabel(m.label))}</small><strong>${esc(m.value)}</strong></div>`).join('')||'<span class="muted">Sin parámetros destacados.</span>'}</div><details class="pool-details"><summary>Todos los controles y mediciones</summary><div class="pool-details-body">${renderPoolMeasurementDetails(pool)}</div></details></article>`;
}

function renderLivePools(){
  const p=state.poolMeasurements;
  if(state.poolMeasurementsLoading&&!p)return '<div class="pool-live-loading"><span class="spinner"></span><span>Leyendo las mediciones de las piscinas…</span></div>';
  if(!p)return '<div class="pool-live-loading is-idle"><span>Los datos se cargan automáticamente desde el control diario de piscinas.</span><button class="btn secondary small" type="button" data-refresh-pools>↻ Cargar ahora</button></div>';
  const fetched=poolPayloadTimestamp(p),stamp=fetched&&Number.isFinite(fetched.getTime())?fetched.toLocaleString('es-ES',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
  const warning=p.warning?`<div class="pool-warning">⚠ ${esc(p.warning)}</div>`:'',cfg=poolPanelConfig();
  const webcams=Object.entries(cfg.webcams||{}).filter(([,v])=>v?.enabled!==false).map(([id,v])=>`<button class="btn secondary small pool-webcam-btn" style="--webcam-btn-bg:${esc(cfg.webcamButtonColor||'#244c78')};--webcam-btn-text:${esc(cfg.webcamButtonText||'#ffffff')}" type="button" data-pool-webcam="${esc(id)}">📹 ${esc(v.label||id)}</button>`).join('');
  const d=p.diagnostics||{};const poolEmpty=p.diagnostics?`<div class="empty">Sin piscinas interpretadas.<br><small>${d.mode?`Modo ${esc(d.mode)} · `:''}selectores ${esc(d.selects??0)} · opciones ${esc((d.options??0)+(d.customOptions??0))} · intentos ${esc(d.attempted??d.tried??0)}${d.networkResponses!==undefined?` · respuestas de red ${esc(d.networkResponses)}`:''}${d.detectedPools!==undefined?` · piscinas ${esc(d.detectedPools)}`:''}</small></div>`:'<div class="empty">La fuente no ha devuelto piscinas.</div>';
  const parts={webcams:webcams?`<div class="pool-webcam-actions">${webcams}</div>`:'',pools:`<div class="pool-live-grid">${orderedPoolList(p.pools||[]).map(renderPoolCard).join('')||poolEmpty}</div>`,temperatureChart:`<section class="pool-temperature-history"><div class="pool-history-title"><div><span class="header-kicker">Temperatura</span><h4>Evolución de las piscinas</h4></div></div>${renderPoolTemperatureChart(p)}</section>`};
  const main=(cfg.sectionOrder||['webcams','pools','temperatureChart']).filter(id=>['webcams','pools','temperatureChart'].includes(id)&&poolSectionVisible(id)).map(id=>parts[id]||'').join('');
  return `${warning}<div class="pool-live-toolbar"><div><strong>Control diario de piscinas</strong><small>Fuente: Galileus · SILOE · consulta ${esc(stamp)}</small></div><button class="mini-btn" type="button" data-refresh-pools title="Actualizar mediciones">↻</button></div>${main}`;
}
async function fetchPoolMeasurementsWorker(){
  const clientFetchedAt=new Date().toISOString();
  const latest=await callIntegrationWorker({action:'pools'},{authenticated:false,timeoutMs:22000});
  const result=latest?.result||latest;
  let historyPayload=null;
  try{historyPayload=await callIntegrationWorker({action:'monitor-history',type:'pools'},{authenticated:false,timeoutMs:22000});}catch(error){console.warn('Histórico piscinas Worker:',error);}
  const history=(historyPayload?.results||[]).map((item,index)=>{
    const stamp=poolPayloadTimestamp(item);
    return {
      ...item,
      id:`worker-${index}-${String(stamp?.toISOString()||'')}`,
      fetchedAt:stamp?.toISOString()||item?.fetchedAt||item?.checkedAt||item?.receivedAt||'',
      pools:Array.isArray(item?.pools)?item.pools:[]
    };
  }).filter(item=>item.fetchedAt||item.pools.length);
  const warning=[result?.warning,latest?.lastError?.error?`La última consulta automática falló: ${latest.lastError.error}`:''].filter(Boolean).join(' · ');
  return {...result,clientFetchedAt,history,warning,diagnostics:{...(result?.diagnostics||{}),transport:'cloudflare-worker+github-playwright'}};
}
async function waitForPoolsMonitor(startedAt,{timeoutMs=110000}={}){
  const start=Number(startedAt)||Date.now();let last=null;
  while(Date.now()-start<timeoutMs){
    await new Promise(resolve=>setTimeout(resolve,3500));
    try{
      last=await callIntegrationWorker({action:'github-tracker-run-status',type:'pools',startedAfter:new Date(start).toISOString()},{timeoutMs:22000});
      const pct=Number(last?.progress?.percentage)||0;
      if(state.activeTab==='lodging'){
        state.poolMeasurements={...(state.poolMeasurements||{}),source:'Galileus · SILOE · navegador real',fetchedAt:new Date().toISOString(),pools:state.poolMeasurements?.pools||[],history:state.poolMeasurements?.history||[],warning:`Actualizando piscinas con navegador real… ${Math.max(2,pct)}%`,diagnostics:{...(state.poolMeasurements?.diagnostics||{}),monitorRunning:true,progress:pct}};
        render();
      }
      if(last?.run?.status==='completed'){
        if(last.run.conclusion!=='success')throw new Error(last?.diagnostic?.summary||'La consulta de piscinas en GitHub Actions no terminó correctamente.');
        await new Promise(resolve=>setTimeout(resolve,1200));
        return await fetchPoolMeasurementsWorker();
      }
    }catch(error){
      if(/no se encontraron|runfound|en cola/i.test(String(error?.message||'')))continue;
      throw error;
    }
  }
  throw new Error('La consulta de piscinas sigue ejecutándose. Vuelve a pulsar actualizar en unos segundos.');
}
async function runPoolsMonitorNow(){
  const startedAt=Date.now();
  const launch=await callIntegrationWorker({action:'github-pools-run'},{timeoutMs:35000});
  if(launch?.workflowTriggered!==true)throw new Error('No se pudo lanzar el monitor de piscinas.');
  toast(launch?.automationUpdated?'Monitor de piscinas preparado. Leyendo Galileus…':'Leyendo Galileus con navegador real…');
  return waitForPoolsMonitor(startedAt);
}
function compactPoolError(error){
  const code=String(error?.code||'').replace(/^functions\//,'').trim();
  const details=(typeof error?.details==='string'?error.details:(error?.details?.message||'')).trim();
  const raw=[code,error?.message,details].map(v=>String(v||'').trim()).filter(Boolean);
  const unique=[];for(const item of raw){if(!unique.some(x=>x.toLocaleLowerCase('es')===item.toLocaleLowerCase('es')))unique.push(item);}
  return unique.join(' · ')||'No se pudieron actualizar las piscinas.';
}
async function loadPoolMeasurements({force=false,silent=true}={}){
  if(state.poolMeasurementsLoading)return state.poolMeasurements;state.poolMeasurementsLoading=true;if(state.activeTab==='lodging')render();
  try{
    const data=force?await runPoolsMonitorNow():await fetchPoolMeasurementsWorker();
    state.poolMeasurements=data||{source:'Galileus · SILOE',fetchedAt:new Date().toISOString(),pools:[],history:[],warning:'La fuente no ha devuelto datos todavía.'};
    if(!silent)toast((state.poolMeasurements.pools||[]).length?'Mediciones de piscinas actualizadas.':'Consulta realizada; revisa el diagnóstico mostrado.');
    return state.poolMeasurements;
  }catch(error){
    const message=compactPoolError(error);
    const noPrevious=!state.poolMeasurements||(state.poolMeasurements.pools||[]).length===0;
    const firstRunMissing=/todav[ií]a no hay resultados|ejecuta primero el monitor|no hay resultados autom[aá]ticos/i.test(message);
    if(noPrevious)state.poolMeasurements={source:'Galileus · SILOE · navegador real',fetchedAt:new Date().toISOString(),pools:[],history:[],warning:firstRunMissing?'Preparando la primera lectura automática de las piscinas…':message,diagnostics:{fatal:!firstRunMissing,clientError:{message},transport:'cloudflare-worker+github-playwright'}};
    else state.poolMeasurements={...state.poolMeasurements,warning:message,diagnostics:{...(state.poolMeasurements.diagnostics||{}),clientError:{message}}};
    if(silent&&firstRunMissing&&!state.poolAutoMonitorStarted){state.poolAutoMonitorStarted=true;setTimeout(()=>loadPoolMeasurements({force:true,silent:true}).catch(()=>{}),250);}
    if(!silent)toast(message,'error');console.warn('Piscinas:',error);return state.poolMeasurements;
  }finally{state.poolMeasurementsLoading=false;if(state.activeTab==='lodging')render();}
}
function loadHlsLibrary(){
  if(window.Hls)return Promise.resolve(window.Hls);return new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-hls-lib]');if(existing){existing.addEventListener('load',()=>resolve(window.Hls),{once:true});existing.addEventListener('error',reject,{once:true});return;}const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/hls.js@1/dist/hls.min.js';script.async=true;script.dataset.hlsLib='1';script.onload=()=>resolve(window.Hls);script.onerror=()=>reject(new Error('No se pudo cargar el reproductor HLS.'));document.head.appendChild(script);});
}
function webcamResponseLooksLikeWholePage(data,key=''){
  const mode=String(data?.mode||'').toLowerCase();
  if(mode!=='iframe')return false;
  try{
    const u=new URL(String(data?.url||''),location.href),host=u.hostname.toLowerCase(),path=u.pathname.replace(/\/+$/,'').toLowerCase();
    if(key==='el-perchel'){
      // Lista blanca: nunca aceptar páginas normales de CanariasLife/Skyline.
      if(/(^|\.)canariaslife\.com$/i.test(host))return true;
      if(/(^|\.)skylinewebcams\.com$/i.test(host))return true;
      // Solo un host de embed inequívoco puede pasar como iframe.
      if(!/(^|\.)embed\.skylinewebcams\.com$/i.test(host))return true;
      if(!path||path==='/')return true;
    }
    return false;
  }catch{return true;}
}
function webcamResponseIsStrictlyPlayable(data,key=''){
  if(!data?.url)return false;
  const mode=String(data.mode||'').toLowerCase();
  try{
    const u=new URL(String(data.url),location.href),host=u.hostname.toLowerCase(),path=u.pathname.toLowerCase();
    if(mode==='video')return /\.(?:m3u8|mp4)(?:$|\?)/i.test(`${path}${u.search}`);
    if(mode==='iframe'){
      if(key==='el-perchel')return /(^|\.)embed\.skylinewebcams\.com$/i.test(host)&&path!=='/'&&!/\/img\//i.test(path);
      return !webcamResponseLooksLikeWholePage(data,key);
    }
    if(mode==='image')return true;
    return false;
  }catch{return false;}
}
async function mountDirectWebcam(player,data){
  if(!player||!data?.url)return;
  if(state.webcamRefreshTimer){clearInterval(state.webcamRefreshTimer);state.webcamRefreshTimer=null;}
  if(data.mode==='image'){
    const base=String(data.url);const bust=()=>`${base}${base.includes('?')?'&':'?'}_mfe=${Date.now()}`;
    const badge=data.live===false?'● FOTOGRAMA ACTUALIZADO':'● EN DIRECTO';
    player.innerHTML=`<div class="webcam-live-image-wrap"><img class="webcam-live-image" src="${esc(bust())}" alt="${esc(data.title||'Webcam')}"><div class="webcam-live-badge">${esc(badge)}</div>${data.note?`<small>${esc(data.note)}</small>`:''}</div>`;
    const img=player.querySelector('.webcam-live-image');if(img){img.addEventListener('error',()=>{if(!img.isConnected)return;player.innerHTML=`<div class="webcam-error"><strong>No se ha podido cargar la imagen de la webcam.</strong><span>El proveedor no ha devuelto un fotograma válido en este momento.</span></div>`;if(state.webcamRefreshTimer){clearInterval(state.webcamRefreshTimer);state.webcamRefreshTimer=null;}},{once:true});}state.webcamRefreshTimer=setInterval(()=>{if(!img?.isConnected){clearInterval(state.webcamRefreshTimer);state.webcamRefreshTimer=null;return;}img.src=bust();},Math.max(8000,Number(data.refreshMs)||15000));return;
  }
  if(data.mode==='iframe'){player.innerHTML=`<iframe class="webcam-direct-frame" src="${esc(data.url)}" title="${esc(data.title||'Webcam en directo')}" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe>`;return;}
  player.innerHTML=`<video class="webcam-direct-video" controls autoplay muted playsinline></video>`;const video=player.querySelector('video');
  if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=data.url;video.play().catch(()=>{});return;}
  try{const Hls=await loadHlsLibrary();if(Hls?.isSupported?.()){const hls=new Hls({enableWorker:true,lowLatencyMode:true});hls.loadSource(data.url);hls.attachMedia(video);hls.on(Hls.Events.MANIFEST_PARSED,()=>video.play().catch(()=>{}));video._mfeHls=hls;return;}}catch(error){console.warn(error);}
  video.src=data.url;video.play().catch(()=>{});
}
async function openPoolWebcam(key){
  const titles={'santa-agueda':'Santa Águeda · El Pajar','el-perchel':'Playa de El Perchel'},title=titles[key]||'Webcam en directo';
  openModal(`<div class="modal-head webcam-modal-head"><div><span class="header-kicker">EN DIRECTO</span><h3>${esc(title)}</h3></div><button class="close-btn" data-close-modal>×</button></div><div class="webcam-player-shell" data-webcam-player><div class="webcam-loading"><span class="spinner"></span><span>Conectando con la webcam…</span></div></div>`,true);
  try{
    // v2.3.41 · Webcam El Perchel: whitelist estricta + fotograma sin caché; nunca cargar páginas completas.
    // El fotograma queda únicamente como respaldo si el proveedor no expone un directo compatible.
    let data;
    data=state.webcamEmbedCache?.[key];
    if(!data){
      try{
        data=await callIntegrationWorker({action:'webcam',key,preferImage:false,preferLive:true},{authenticated:false,timeoutMs:30000});
        if(webcamResponseLooksLikeWholePage(data,key)||!webcamResponseIsStrictlyPlayable(data,key)){
          console.warn('Webcam: respuesta no reproducible o página completa; se rechaza.',data);
          throw new Error('El proveedor no ofrece un reproductor externo compatible.');
        }
      }
      catch(workerError){
        console.warn('Webcam Worker',workerError);
        if(key==='el-perchel'){
          // No volver jamás a Firebase/CanariasLife para El Perchel: ese fallback podía cargar la web completa.
          data=await callIntegrationWorker({action:'webcam',key,preferImage:true,preferLive:false},{authenticated:false,timeoutMs:30000});
          if(!data||String(data.mode||'').toLowerCase()!=='image')throw workerError;
        }else{
          data=await state.provider.call('getTravelWebcam',{key});
          if(webcamResponseLooksLikeWholePage(data,key)||!webcamResponseIsStrictlyPlayable(data,key))throw workerError;
        }
      }
      state.webcamEmbedCache[key]=data;
    }
    const kicker=$('.webcam-modal-head .header-kicker',els.modal);if(kicker)kicker.textContent=data?.live===false?'FOTOGRAMA ACTUALIZADO':'EN DIRECTO';
    const target=$('[data-webcam-player]',els.modal);if(target)await mountDirectWebcam(target,data);
  }catch(error){const target=$('[data-webcam-player]',els.modal);if(target)target.innerHTML=`<div class="webcam-error"><strong>No se ha podido abrir la webcam.</strong><span>${esc(error.message||'El proveedor no expone un reproductor compatible en este momento.')}</span></div>`;}
}

function renderLodgingPage(){
  const l=state.data.cover?.lodging||{};
  const cordialTracker=state.data.trackers?.cordial||{};
  const s=state.data.settings||{};
  const lc=l.imageCrop||{x:50,y:50,zoom:1};
  const reviewDefaults=defaultLodgingReviewButtons();
  const reviewLinks=[
    isValidUrl(l.googleReviewsUrl)?coloredServiceLink(l.googleReviewsUrl,l.googleReviewsLabel||reviewDefaults.googleReviewsLabel,l.googleReviewsColor||reviewDefaults.googleReviewsColor,serviceIconMarkup(l.googleReviewsIcon,l.googleReviewsIconUrl,brandIconMarkup('google')),'lodging-review-link','googlemaps'):'',
    isValidUrl(l.tripadvisorReviewsUrl)?coloredServiceLink(l.tripadvisorReviewsUrl,l.tripadvisorReviewsLabel||reviewDefaults.tripadvisorReviewsLabel,l.tripadvisorReviewsColor||reviewDefaults.tripadvisorReviewsColor,serviceIconMarkup(l.tripadvisorReviewsIcon,l.tripadvisorReviewsIconUrl,brandIconMarkup('tripadvisor')),'lodging-review-link','tripadvisor'):'',
    isValidUrl(l.bookingReviewsUrl)?coloredServiceLink(l.bookingReviewsUrl,l.bookingReviewsLabel||reviewDefaults.bookingReviewsLabel,l.bookingReviewsColor||reviewDefaults.bookingReviewsColor,serviceIconMarkup(l.bookingReviewsIcon,l.bookingReviewsIconUrl,brandIconMarkup('booking')),'lodging-review-link booking-review-link','booking'):''
  ].filter(Boolean).join('');
  const budgetGroup=(state.data.budget?.groups||[]).find(g=>g.id==='g-lodging'||/cordial|alojamiento/i.test(String(g.name||'')));
  const reservedTotal=budgetGroup?sum((budgetGroup.items||[]).map(i=>num(i.amount))):0;
  const paidTotal=budgetGroup?sum((budgetGroup.items||[]).filter(i=>i.status==='paid').map(i=>num(i.amount))):0;
  const reservationCode=(budgetGroup?.items||[]).map(i=>i.name).filter(Boolean).join(' · ');
  const lodgingDoc=(state.data.cover?.documents||[]).find(d=>String(d.id||'')==='doc-lodging'||/alojamiento|cordial/i.test(`${d.title||''} ${d.subtitle||''}`));
  const storedGuideLabel=String(l.guestGuideLabel||'').trim();const guideDisplayLabel=(!storedGuideLabel||/gu[ií]a del resort|piscinas y servicios|temperatura piscinas/i.test(storedGuideLabel))?'Temp Piscinas':storedGuideLabel;const guideButton=`<button type="button" class="link-btn lodging-guide-link" data-scroll-pools>🌡️ <span>${esc(guideDisplayLabel)}</span></button>`;const sourceGuideLink=isValidUrl(l.guestGuideUrl)?safeLink(l.guestGuideUrl,'Abrir fuente original','↗','lodging-guide-source-link'):'';
  const carousels=(state.data.cover?.mediaCarousels||[]).map((carousel,index)=>coverCarouselPlacement(carousel)==='lodging'?renderLodgingCarouselAccordion(carousel,index):'').join('');
  const mapMode={satellite:'k',hybrid:'h',terrain:'p',map:'m'}[s.mapType]||'k';
  const mapUrl=s.mapEmbedUrl || (s.mapQuery?`https://www.google.com/maps?q=${encodeURIComponent(s.mapQuery)}&output=embed&t=${mapMode}`:'');
  const titleIcon=String(cordialTracker.titleIconUrl||'').trim()?resilientImageMarkup(String(cordialTracker.titleIconUrl||'').trim(),'airline-logo flight-card-airline-logo lodging-title-icon',`<span class="airline-logo flight-card-airline-logo lodging-title-icon emoji-icon">${esc(cordialTracker.titleIcon||TRACKER_DEFAULT_ICONS.cordial||'🏨')}</span>`,false):`<span class="airline-logo flight-card-airline-logo lodging-title-icon emoji-icon">${esc(cordialTracker.titleIcon||TRACKER_DEFAULT_ICONS.cordial||'🏨')}</span>`;
  const photo=isImageSource(l.imageUrl)?`<button class="lodging-image lodging-page-image clickable-image" style="--lodging-img:url('${esc(l.imageUrl)}');--lodging-pos:${num(lc.x)||50}% ${num(lc.y)||50}%;--lodging-zoom:${Math.max(1,num(lc.zoom)||1)}" data-image-popup="${esc(l.imageUrl)}" data-image-title="${esc(l.name)}" aria-label="Ampliar imagen del alojamiento"></button>`:'';
  return `${lockedBanner()}${pageHead('Alojamiento','',canEdit()?'<button class="btn secondary" data-edit-lodging>✎ Editar</button>':'')}
  <section class="card lodging-page-hero provider-gradient-card" style="--provider-g1:${esc(l.gradient1||providerPalette(l).g1)};--provider-g2:${esc(l.gradient2||providerPalette(l).g2)};--provider-title-text:${esc(l.textColor||'#ffffff')}">
    <div class="lodging-page-title">${titleIcon}<div><span class="header-kicker">Estancia actual</span><h3>${esc(l.name||'Alojamiento')}</h3></div></div>
    <div class="lodging-page-dates"><div class="date-chip"><small class="muted">Entrada</small><br><strong>${formatDate(l.checkIn)}</strong></div><div class="date-chip"><small class="muted">Salida</small><br><strong>${formatDate(l.checkOut)}</strong></div></div>
    <div class="lodging-page-actions">${safeLink(l.website,'Web','🌐','lodging-quick-link')}${safeLink(mapsDirectionsUrl(l.address||l.name,l.mapsUrl),'Cómo llegar',googleMapsIconMarkup(),'lodging-quick-link maps-route-link')}${guideButton}${reviewLinks}</div>
    ${photo}
  </section>
  <div class="lodging-page-grid">
    <section class="card lodging-info-panel"><div class="card-body"><h3>Reserva</h3><div class="lodging-reservation-kpis"><div><small>Localizador</small><strong>${esc(reservationCode||lodgingDoc?.subtitle||'—')}</strong></div><div><small>Importe reservado</small><strong>${reservedTotal?formatMoney(reservedTotal):'—'}</strong></div><div><small>Pagado</small><strong>${reservedTotal?formatMoney(paidTotal):'—'}</strong></div></div>${lodgingDoc?`<div class="lodging-reservation-doc">${renderDocument(lodgingDoc,(state.data.cover.documents||[]).indexOf(lodgingDoc))}</div>`:''}<div class="page-actions"><button class="btn secondary small" type="button" data-lodging-open-tab="budget">💶 Abrir presupuesto</button><button class="btn secondary small" type="button" data-lodging-open-tab="trackers">📈 Seguimiento de precio</button></div></div></section>
    ${poolPanelConfig().enabled===false?'':(()=>{const pc=poolPanelConfig(),extras={source:sourceGuideLink?`<div class="lodging-guide-callout"><span>También puedes consultar la fuente original si necesitas comprobar el parte completo.</span>${sourceGuideLink}</div>`:''},extraMarkup=(pc.sectionOrder||[]).filter(id=>id==='source'&&poolSectionVisible(id)).map(id=>extras[id]||'').join('');return `<section class="card lodging-info-panel lodging-pools-panel"><div class="card-body"><div class="lodging-pools-heading"><div><span class="header-kicker">${esc(pc.kicker||'DATOS EN DIRECTO')}</span><h3>${esc(pc.title||'Piscinas y servicios')}</h3></div></div>${renderLivePools()}${extraMarkup}</div></section>`;})()}
  </div>
  ${carousels?`<section class="lodging-page-section"><div class="section-title"><span>🗂️ PLANOS E INSTRUCCIONES</span></div><div class="lodging-embedded-media">${carousels}</div></section>`:''}
  <section class="lodging-page-section"><div class="section-title"><span>📍 UBICACIÓN · ${esc(({satellite:'SATÉLITE',hybrid:'HÍBRIDO',terrain:'TERRENO',map:'MAPA'})[s.mapType]||'SATÉLITE')}</span></div>${mapUrl?`<iframe class="map-frame lodging-map-frame" src="${esc(mapUrl)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>`:'<div class="map-placeholder lodging-map-placeholder">Añade una ubicación o URL de mapa en Configuración.</div>'}</section>${multiStageEnabled()?`<section class="stage-lodging-detail"><div class="section-title"><span>🏨 Segunda estancia · Fuerteventura</span></div>${renderStage2LodgingCard()}${renderStage2LodgingReservationDetails()}</section>`:''}`;
}

binders.lodging=()=>{
  bindStageControls();
  $$('[data-edit-lodging]').forEach(b=>b.addEventListener('click',editLodging));
  $$('[data-scroll-pools]').forEach(b=>b.addEventListener('click',()=>document.querySelector('.lodging-pools-panel')?.scrollIntoView({behavior:'smooth',block:'start'})));
  $('[data-lodging-open-tab]').forEach(b=>b.addEventListener('click',()=>navigateToTab(String(b.dataset.lodgingOpenTab||'cover'))));
  $('[data-stage-lodging-track]').forEach(b=>b.addEventListener('click',()=>navigateToTab('trackers')));
  $$('[data-refresh-pools]').forEach(b=>b.addEventListener('click',()=>loadPoolMeasurements({force:true,silent:false})));
  $$('[data-pool-webcam]').forEach(b=>b.addEventListener('click',()=>openPoolWebcam(String(b.dataset.poolWebcam||''))));
  $$('[data-lodging-carousel-details]').forEach(node=>node.addEventListener('toggle',()=>{const id=String(node.dataset.lodgingCarouselDetails||'');if(!id)return;state.coverCarouselOpen[id]=node.open;if(node.open){$$('[data-lodging-carousel-details]').forEach(other=>{if(other===node||!other.open)return;const otherId=String(other.dataset.lodgingCarouselDetails||'');other.open=false;if(otherId)state.coverCarouselOpen[otherId]=false;});}}));
  if(!state.poolMeasurements&&!state.poolMeasurementsLoading)void loadPoolMeasurements({silent:true});
};

function renderBudgetPaidProgress(stats){
  const total=Math.max(0,num(stats.total)),paid=Math.max(0,num(stats.paid));
  const pct=total>0?Math.max(0,Math.min(100,paid/total*100)):0;
  return `<section class="budget-paid-progress" aria-label="Progreso de pago del presupuesto"><div class="budget-paid-progress-head"><div><span>Progreso de pago</span><strong>${pct.toLocaleString('es-ES',{maximumFractionDigits:1})}%</strong></div><div class="budget-paid-progress-values"><span>Pagado <b>${formatMoney(paid)}</b></span><span>Total <b>${formatMoney(total)}</b></span></div></div><div class="budget-paid-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${Math.min(paid,total)}" aria-label="${formatMoney(paid)} pagados de ${formatMoney(total)}"><span class="budget-paid-progress-fill" style="width:${pct.toFixed(2)}%"></span><span class="budget-paid-progress-dot" style="left:${pct.toFixed(2)}%"></span></div><div class="budget-paid-progress-scale"><span>${formatMoney(0)}</span><span>${formatMoney(total)}</span></div></section>`;
}

function renderBudgetGroup(group,gIndex) {
  const isFlightGroup=group.id==='g-flights';
  const entries=effectiveBudgetEntries(group);
  const total=sum(entries.map(entry=>itemAmount(entry.item)));
  const rows=entries.map(({item,index,automatic})=>{
    const rowIconUrl=item.iconUrl||group.iconUrl||"";
    const rowIcon=item.icon||group.icon||"💳";
    const compactRowIcon=iconMarkup(rowIcon,rowIconUrl,'budget-item-icon');
    const sourceLabel=!automatic&&item.source?`<small class="muted">Automático: Lista de compra</small>`:"";
    const concept=`<div class="budget-item-concept" style="display:flex!important;align-items:center!important;gap:10px!important;min-width:0!important"><span class="budget-item-icon-frame" style="display:grid!important;place-items:center!important;flex:0 0 36px!important;width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;max-width:36px!important;max-height:36px!important;overflow:hidden!important"><span class="budget-item-icon-inner">${compactRowIcon}</span></span><span class="budget-item-copy" style="display:flex!important;flex-direction:column!important;justify-content:center!important;min-width:0!important"><strong>${esc(item.name)}</strong>${sourceLabel}</span></div>`;
    const detailLinks=automatic
      ? (item.autoType==="bus"
        ? `${(item.files||[]).map(f=>renderFileButton(f,item.name)).join('')}`
        : `${item.autoType==="extra"&&isValidUrl(item.fileUrl)?popupFileLink(item.fileUrl,"Ver archivo","📄"):""}<button class="link-btn" type="button" data-open-real-purchases="${item.autoType||""}">🧾 ${item.autoType==="extra"?"Ver":"Ver compras"}</button>`)
      : `${isValidUrl(item.url)?(isFilePreviewUrl(item.url)?popupFileLink(item.url,item.webLabel||"Ver archivo","📄"):safeLink(item.url,item.webLabel||"Web","↗")):''}${(item.files||[]).map(f=>renderFileButton(f,item.name)).join('')}`;
    const preview=budgetPreviewAsset(group,item);
    const previewMarkup=preview?`<button class="budget-detail-preview ${preview.kind==='cordial'?'is-cover':''} clickable-image" type="button" data-image-popup="${esc(preview.url)}" data-image-title="${esc(preview.title)}" aria-label="Ampliar imagen de ${esc(preview.title)}"><img src="${esc(preview.url)}" alt="${esc(preview.title)}" loading="lazy"></button>`:'';
    const status=automatic
      ? (item.autoType==="extra"
        ? `<button class="status-pill ${item.status==="paid"?"paid":"unpaid"}" data-toggle-extra-paid="${esc(item.sourceId)}" ${canEdit()?"":"disabled"}>${item.status==="paid"?"PAGADO":"NO PAGADO"}</button>`
        : item.autoType==="bus"
          ? `<button class="status-pill ${item.status==="paid"?"paid":"unpaid"}" data-toggle-bus-paid="${esc(item.sourceId)}" ${canEdit()?"":"disabled"}>${item.status==="paid"?"PAGADO":"NO PAGADO"}</button>`
          : `<span class="status-pill paid automatic-status">PAGADO</span>`)
      : `<button class="status-pill ${item.status==="paid"?"paid":"unpaid"}" data-toggle-paid="${gIndex}:${index}" ${canEdit()?"":"disabled"}>${item.status==="paid"?"PAGADO":"NO PAGADO"}</button>`;
    const actions=canEdit()
      ? (automatic
        ? `<td data-label="Acciones"><span class="budget-actions-wrap">${item.autoType==="extra"?`<div class="row-actions"><button class="mini-btn" data-edit-source-extra="${esc(item.sourceId)}" title="Editar en Compra real">✎</button><span class="auto-row-mark auto-row-sync" title="Sincronizado automáticamente con Compra real" aria-label="Sincronizado automáticamente con Compra real">↻</span></div>`:item.autoType==="bus"?`<div class="row-actions"><button class="mini-btn action-clip" data-manage-source-bus-files="${esc(item.sourceId)}" title="Billetes PDF y archivos" aria-label="Billetes PDF y archivos">📎</button><button class="mini-btn" data-edit-source-bus="${esc(item.sourceId)}" title="Editar autobús">✎</button><span class="auto-row-mark auto-row-sync" title="Sincronizado automáticamente con Datos del viaje" aria-label="Sincronizado automáticamente con Datos del viaje">↻</span></div>`:`<span class="auto-row-mark auto-row-sync" title="Elemento automático" aria-label="Elemento automático">↻</span>`}</span></td>`
        : `<td data-label="Acciones"><div class="row-actions"><button class="mini-btn" data-manage-budget-files="${gIndex}:${index}" title="Archivos y enlaces" aria-label="Archivos y enlaces">📎</button><button class="mini-btn" data-edit-budget-item="${gIndex}:${index}" title="Editar concepto, texto e icono">✎</button><button class="mini-btn" data-delete-budget-item="${gIndex}:${index}">×</button></div></td>`)
      : "";
    const detailClass=`budget-detail${preview?' has-preview':''}`;
    const flight=isFlightGroup?budgetFlightForItem(item):null;
    const flightCells=isFlightGroup?`<td data-label="Horario" class="budget-flight-meta">${flight?`${formatTime(flight.departure)}–${formatTime(flight.arrival)}`:''}</td><td data-label="Duración" class="budget-flight-meta">${flight?esc(flightDuration(flight)):''}</td><td data-label="Vuelo" class="budget-flight-meta budget-flight-number">${flight?esc(flight.number||''):''}</td>`:'';
    return `<tr class="${automatic?"automatic-budget-row ":""}${preview?'budget-row-has-preview':''}${flight?' budget-flight-data-row':''}"><td data-label="Concepto">${concept}</td><td data-label="Detalle y archivos"><div class="${detailClass}"><div class="budget-detail-copy"><span>${esc(item.detail||"")}</span><div class="budget-links">${detailLinks}</div></div>${previewMarkup}</div></td>${flightCells}<td data-label="Importe" class="amount">${formatMoney(itemAmount(item))}</td><td data-label="Estado">${status}</td>${actions}</tr>`;
  }).join("");
  const headerBus=group.id==='g-bus'?(state.data.cover.buses||[]).find(bus=>bus&&bus.visible!==false)||(state.data.cover.buses||[])[0]:null;
  // En el bloque automático de autobús manda siempre el icono actual del trayecto.
  // Evita que quede fijada una imagen antigua guardada previamente en el grupo.
  const headerIconUrl=headerBus?busIdentityVisualUrl(headerBus,(state.data.cover.buses||[]).indexOf(headerBus)):(group.iconUrl||'');
  const headerIcon=headerBus?(headerBus.icon||group.icon||'🚌'):(group.icon||'◼');
  const flightCols=isFlightGroup?'<col class="budget-col-flight-time"><col class="budget-col-flight-duration"><col class="budget-col-flight-number">':'';
  const flightHeaders=isFlightGroup?'<th>Horario</th><th>Duración</th><th>Vuelo</th>':'';
  const titleGradient1=headerBus?(headerBus.gradient1||headerBus.color||group.gradient1||group.color):(group.gradient1||group.color);
  const titleGradient2=headerBus?(headerBus.gradient2||headerBus.color||group.gradient2||group.color):(group.gradient2||group.color);
  const titleTextColor=headerBus?(headerBus.textColor||group.textColor||'#ffffff'):(group.textColor||'#ffffff');
  const columnCount=(isFlightGroup?7:4)+(canEdit()?1:0);
  return `<article class="card budget-group-card" data-sort-item="budget-group|${gIndex}" style="--group-color:${esc(group.color)}"><div class="section-title" style="--g1:${esc(titleGradient1)};--g2:${esc(titleGradient2)};--title-text:${esc(titleTextColor)}"><span class="section-title-label">${iconMarkup(headerIcon,headerIconUrl,"section-icon")} ${esc(group.name)}</span>${editButtons(`<div class="section-actions">${sortDragHandle(`budget-group|${gIndex}`,'Arrastrar bloque')}<button class="mini-btn" data-add-budget-item="${gIndex}">＋</button><button class="mini-btn" data-edit-budget-group="${gIndex}">✎</button><button class="mini-btn" data-delete-budget-group="${gIndex}">×</button></div>`)}</div><div class="table-wrap"><table class="budget-table ${isFlightGroup?'budget-flight-table':''}"><colgroup><col class="budget-col-name"><col class="budget-col-detail">${flightCols}<col class="budget-col-amount"><col class="budget-col-status">${canEdit()?'<col class="budget-col-actions">':''}</colgroup><thead><tr><th>Concepto</th><th>Detalle y archivos</th>${flightHeaders}<th class="amount">Importe</th><th>Estado</th>${canEdit()?"<th></th>":""}</tr></thead><tbody>${rows||`<tr><td colspan="${columnCount}" class="empty">Todavía no hay conceptos.</td></tr>`}</tbody></table></div><div class="group-total"><span>Total</span><strong>${formatMoney(total)}</strong></div></article>`;
}
function donutData() {
  const groups=state.data.budget.groups.map(g=>({name:g.name,color:g.color,value:sum(effectiveBudgetEntries(g).map(entry=>itemAmount(entry.item)))})).filter(x=>x.value>0); const total=sum(groups.map(x=>x.value)); let acc=0;
  groups.forEach(g=>{g.percentage=total?g.value/total*100:0;g.start=acc;acc+=g.percentage;});
  return {groups,total};
}
function renderDonutChart(chart) {
  const circumference=2*Math.PI*48;
  const segments=chart.groups.map((g,i)=>{const length=g.percentage/100*circumference;const offset=-(g.start/100*circumference);return `<circle class="donut-segment" cx="60" cy="60" r="48" fill="none" stroke="${esc(g.color)}" stroke-width="18" stroke-dasharray="${length} ${circumference}" stroke-dashoffset="${offset}" transform="rotate(-90 60 60)" data-chart-name="${esc(g.name)}" data-chart-value="${g.value}" data-chart-pct="${g.percentage.toFixed(1)}" data-tracker-chart-tooltip="${esc(`${g.name} · ${formatMoney(g.value)} · ${g.percentage.toFixed(1)}%`)}" tabindex="0"><title>${esc(g.name)} · ${formatMoney(g.value)} · ${g.percentage.toFixed(1)}%</title></circle>`;}).join('');
  return `<div class="donut-wrap"><div class="donut-chart"><svg class="donut-svg" viewBox="0 0 120 120" role="img" aria-label="Distribución del gasto"><circle cx="60" cy="60" r="48" fill="none" stroke="rgba(255,255,255,.06)" stroke-width="18"></circle>${segments}</svg><div class="donut-center" data-donut-center data-total="${formatMoney(chart.total)}"><strong>${formatMoney(chart.total)}</strong><span>Total</span></div></div></div><div class="chart-legend">${chart.groups.map(g=>`<div class="legend-row"><span class="legend-dot" style="background:${esc(g.color)}"></span><span>${esc(g.name)} <small>${g.percentage.toFixed(1)}%</small></span><strong>${formatMoney(g.value)}</strong></div>`).join("")}</div>`;
}
function bindDonutInteractions(root=document) {
  $$('[data-donut-center]',root).forEach(center=>{
    const scope=center.closest('.donut-wrap')||root;
    const restore=()=>{center.innerHTML=`<strong>${esc(center.dataset.total||'')}</strong><span>Total</span>`;};
    $$('[data-chart-name]',scope).forEach(segment=>{
      const show=()=>{center.innerHTML=`<strong class="donut-hover-name">${esc(segment.dataset.chartName)}</strong><span>${formatMoney(segment.dataset.chartValue)} · ${esc(segment.dataset.chartPct)}%</span>`;segment.classList.add('active');};
      const hide=()=>{segment.classList.remove('active');restore();};
      segment.addEventListener('mouseenter',show);segment.addEventListener('focus',show);segment.addEventListener('mouseleave',hide);segment.addEventListener('blur',hide);segment.addEventListener('pointerdown',show);
    });
  });
}
function trackerChartTooltipElement(){
  let tip=document.getElementById('tracker-chart-tooltip');
  if(!tip){tip=document.createElement('div');tip.id='tracker-chart-tooltip';tip.className='tracker-chart-tooltip';tip.setAttribute('role','tooltip');document.body.appendChild(tip);}
  return tip;
}
function bindTrackerChartTooltips(root=document){
  const nodes=$$('[data-tracker-chart-tooltip]',root);if(!nodes.length)return;
  const tip=trackerChartTooltipElement();let hideTimer=null;
  const move=e=>{const gap=14,maxX=Math.max(gap,window.innerWidth-tip.offsetWidth-gap),maxY=Math.max(gap,window.innerHeight-tip.offsetHeight-gap);tip.style.left=`${Math.min(maxX,Math.max(gap,e.clientX+14))}px`;tip.style.top=`${Math.min(maxY,Math.max(gap,e.clientY-16))}px`;};
  const show=(node,e,sticky=false)=>{if(hideTimer){clearTimeout(hideTimer);hideTimer=null;}tip.textContent=node.dataset.trackerChartTooltip||'';tip.classList.add('is-visible');move(e);if(sticky)hideTimer=setTimeout(()=>tip.classList.remove('is-visible'),4200);};
  const hide=()=>{if(!hideTimer)tip.classList.remove('is-visible');};
  nodes.forEach(node=>{
    if(node.dataset.chartTooltipBound==='1')return;node.dataset.chartTooltipBound='1';
    node.addEventListener('pointerenter',e=>show(node,e));node.addEventListener('pointermove',move);node.addEventListener('pointerleave',hide);
    node.addEventListener('focus',()=>{const r=node.getBoundingClientRect();show(node,{clientX:r.left+r.width/2,clientY:r.top+r.height/2});});node.addEventListener('blur',hide);
    node.addEventListener('pointerdown',e=>{e.stopPropagation();show(node,e,true);});
  });
}
function chartExpansionTitle(wrapper){
  const svg=wrapper?.querySelector?.('svg[aria-label]');
  return String(svg?.getAttribute('aria-label')||'Gráfico').trim()||'Gráfico';
}
function chartExpansionCompanionMarkup(wrapper){
  const accepted=/\b(?:tracker-multi-chart-legend|vueling-chart-legend|shopping-history-chart-legend|chart-legend)\b/;
  const prev=wrapper?.previousElementSibling,next=wrapper?.nextElementSibling;
  const before=prev&&accepted.test(String(prev.className||''))?prev.outerHTML:'';
  const after=next&&accepted.test(String(next.className||''))?next.outerHTML:'';
  return {before,after};
}
function openExpandedChart(wrapper){
  if(!wrapper)return;
  const title=chartExpansionTitle(wrapper),companions=chartExpansionCompanionMarkup(wrapper),clone=wrapper.cloneNode(true);
  clone.classList.remove('chart-expandable');clone.removeAttribute('data-chart-expand-bound');clone.classList.add('chart-expanded-copy');
  clone.querySelectorAll('[data-chart-tooltip-bound]').forEach(node=>node.removeAttribute('data-chart-tooltip-bound'));
  openModal(`<div class="modal-head chart-zoom-head"><div><span class="header-kicker">GRÁFICO AMPLIADO</span><h3>${esc(title)}</h3><small>Pulsa cualquier punto para ver su dato exacto.</small></div><button class="close-btn" data-close-modal>×</button></div><div class="chart-zoom-shell">${companions.before}${clone.outerHTML}${companions.after}</div>`,true);
  bindTrackerChartTooltips(els.modal);bindDonutInteractions(els.modal);
}
function bindInteractiveCharts(root=document){
  const selector='.pool-chart-wrap,.cordial-chart-wrap,.shopping-history-chart-wrap,.donut-wrap';
  $$(selector,root).forEach(wrapper=>{
    if(wrapper.closest('.chart-zoom-shell'))return;
    if(wrapper.dataset.chartExpandBound==='1')return;wrapper.dataset.chartExpandBound='1';wrapper.classList.add('chart-expandable');wrapper.setAttribute('title','Pulsa para ampliar el gráfico');
    wrapper.addEventListener('click',event=>{if(event.target.closest('[data-chart-name],a,button,input,select,label'))return;openExpandedChart(wrapper);});
  });
}

