function budgetVisibilityMeta(id){
  const key=String(id||'');
  if(key==='summary')return ['💶','Resumen del presupuesto'];
  if(key==='progress')return ['📊','Progreso de pago'];
  if(key==='side:carKm'){const cfg=budgetSideCardConfig('carKm');return [cfg.icon||'🚗',cfg.title||'Kilómetros coche'];}
  if(key==='side:distribution'){const cfg=budgetSideCardConfig('distribution');return [cfg.icon||'📈',cfg.title||'Distribución'];}
  if(key.startsWith('group:')){
    const groupId=key.slice(6),group=(state.data.budget.groups||[]).find((item,index)=>String(item?.id||`group-${index}`)===groupId);
    return [group?.icon||'💳',group?.name||'Grupo de presupuesto'];
  }
  return ['▣',key||'Elemento'];
}
function budgetVisibilityButton(id,label=''){
  if(!canEdit())return '';
  const meta=budgetVisibilityMeta(id),title=label||meta[1];
  return `<button type="button" class="mini-btn budget-visibility-btn" data-budget-hide="${esc(id)}" title="Ocultar ${esc(title)}" aria-label="Ocultar ${esc(title)}">${coverEyeIconMarkup('budget-eye-icon')}</button>`;
}
function renderBudgetHiddenList(hiddenSet){
  if(!canEdit()||!hiddenSet.size)return '';
  const order=[];
  const push=id=>{if(hiddenSet.has(id)&&!order.includes(id))order.push(id);};
  push('summary');push('progress');
  (state.data.budget.groups||[]).forEach((group,index)=>push(`group:${String(group?.id||`group-${index}`)}`));
  push('side:carKm');push('side:distribution');
  for(const id of hiddenSet)push(id);
  if(!order.length)return '';
  return `<section class="card cover-hidden-list budget-hidden-list"><div class="cover-hidden-list-head"><strong>Elementos ocultos</strong><small>Solo aparece mientras la edición está desbloqueada</small></div><div class="cover-hidden-list-items">${order.map(id=>{const[icon,label]=budgetVisibilityMeta(id);return `<div class="cover-hidden-list-row"><span>${esc(icon)} ${esc(label)}</span><button type="button" class="mini-btn cover-show-btn" data-budget-show="${esc(id)}" title="Volver a mostrar ${esc(label)}" aria-label="Volver a mostrar ${esc(label)}">${coverEyeIconMarkup('budget-eye-icon')}</button></div>`;}).join('')}</div></section>`;
}
function renderBudget() {
  const stats=budgetStats(), chart=donutData(), km=state.data.budget.carKm, driven=(km.initial!==""&&km.final!=="")?num(km.final)-num(km.initial):null;
  const kmCard=budgetSideCardConfig('carKm'),distributionCard=budgetSideCardConfig('distribution');
  const hidden=new Set(state.data.budget.hiddenBlocks||[]);
  const summary=hidden.has('summary')?'':`<div class="budget-hideable-block">${canEdit()?`<div class="budget-visibility-row">${budgetVisibilityButton('summary')}</div>`:''}<section class="kpi-grid budget-summary-grid"><div class="kpi accent"><span>Presupuesto total</span><strong>${formatMoney(stats.total)}</strong></div><div class="kpi"><span>Total por persona</span><strong>${formatMoney(stats.perPerson)}</strong></div><div class="kpi success kpi-with-chart"><div class="kpi-copy"><span>Pagado</span><strong>${formatMoney(stats.paid)}</strong></div>${coverBudgetDonut("Pagado",stats.paid,stats.total,"success")}</div><div class="kpi danger kpi-with-chart"><div class="kpi-copy"><span>Por pagar</span><strong>${formatMoney(stats.unpaid)}</strong></div>${coverBudgetDonut("Pendiente",stats.unpaid,stats.total,"danger")}</div></section></div>`;
  const progress=hidden.has('progress')?'':`<div class="budget-hideable-block">${canEdit()?`<div class="budget-visibility-row">${budgetVisibilityButton('progress')}</div>`:''}${renderBudgetPaidProgress(stats)}</div>`;
  const groups=(state.data.budget.groups||[]).map((group,index)=>{
    const key=`group:${String(group?.id||`group-${index}`)}`;
    if(hidden.has(key))return '';
    return renderBudgetGroup(group,index).replace('<div class="section-actions">',`<div class="section-actions">${budgetVisibilityButton(key,group?.name||'grupo')}`);
  }).join('');
  const kmMarkup=hidden.has('side:carKm')?'':`<article class="card budget-side-card"><div class="section-title" style="--g1:${esc(kmCard.gradient1)};--g2:${esc(kmCard.gradient2)};--title-text:${esc(kmCard.textColor||'#ffffff')}"><span class="section-title-label">${iconMarkup(kmCard.icon,kmCard.iconUrl,'section-icon')} ${esc(kmCard.title)}</span>${editButtons(`<div class="section-actions">${budgetVisibilityButton('side:carKm',kmCard.title)}<button class="mini-btn" data-edit-budget-side="carKm" title="Editar icono y título">✎</button></div>`)}</div><div class="card-body"><div class="km-grid"><label class="field">Iniciales<input data-km="initial" type="number" step="0.1" value="${esc(km.initial)}" ${canEdit()?"":"disabled"}></label><label class="field">Finales<input data-km="final" type="number" step="0.1" value="${esc(km.final)}" ${canEdit()?"":"disabled"}></label><div class="km-result">${driven===null?"—":`${driven.toLocaleString("es-ES")} km`}</div></div></div></article>`;
  const distributionMarkup=hidden.has('side:distribution')?'':`<article class="card budget-side-card"><div class="section-title" style="--g1:${esc(distributionCard.gradient1)};--g2:${esc(distributionCard.gradient2)};--title-text:${esc(distributionCard.textColor||'#ffffff')}"><span class="section-title-label">${iconMarkup(distributionCard.icon,distributionCard.iconUrl,'section-icon')} ${esc(distributionCard.title)}</span>${editButtons(`<div class="section-actions">${budgetVisibilityButton('side:distribution',distributionCard.title)}<button class="mini-btn" data-edit-budget-side="distribution" title="Editar icono y título">✎</button></div>`)}</div>${renderDonutChart(chart)}</article>`;
  const side=[kmMarkup,distributionMarkup].filter(Boolean).join('');
  return `${lockedBanner()}${pageHead("Presupuesto","Control editable de vuelos, autobuses, reservas, compras, extras y pagos",`<button class="btn secondary pdf-action-btn" data-export-budget-pdf>${pdfFileIconMarkup("pdf-action-icon")} Exportar PDF</button>${canEdit()?'<button class="btn primary canary-action-btn" data-add-budget-group>＋ Crear grupo</button>':''}`)}
  ${summary}${progress}
  ${multiStageEnabled()?`<div class="stage-budget-head"><strong>🏝️ Presupuesto por etapas</strong><span>Los importes de la segunda reserva se añaden automáticamente a sus grupos. No los dupliques manualmente.</span></div><div class="stage-card-grid">${stageReservationCard(0,'car')}${stageReservationCard(1,'car')}</div>`:''}<div class="budget-layout"><div class="budget-groups">${groups}</div>${side?`<aside class="budget-side">${side}</aside>`:''}</div>${renderBudgetHiddenList(hidden)}`;
}

