  const total=sum(rows.map(r=>r.total));
  const data=[['Última fecha','Comercio','Producto','Cantidad','Precio ud.','Total'],...rows.map(r=>[r.date,r.store,r.name,r.quantity,r.unitPrice,r.total]),['','','','', 'TOTAL',total]];
