function historyArchiveById(id=''){return (state.data.history?.archives||[]).find((item,index)=>String(item?.id||index)===String(id));}
function historyArchiveSortTime(item={}){
  for(const value of [item.endDate,item.returnDateTime,item.startDate,item.departureDateTime,item.archivedAt]){
    const t=Date.parse(String(value||''));if(Number.isFinite(t))return t;
  }
  const year=num(item.year);return year>0?Date.UTC(year,11,31):0;
}
function sortedHistoryArchives(){
  return [...(state.data.history?.archives||[])].sort((a,b)=>historyArchiveSortTime(b)-historyArchiveSortTime(a)||String(b.archivedAt||'').localeCompare(String(a.archivedAt||'')));
}
function latestHistoryArchiveReference(){return sortedHistoryArchives()[0]||null;}
function archiveDriveFolder(){
  const folder=state.data.settings?.historyDriveFolder||{};
  return folder?.id?{id:String(folder.id),name:String(folder.name||'Carpeta Histórico'),sharedDriveId:String(folder.sharedDriveId||''),sourceMode:String(folder.sourceMode||'my')}:{id:'',name:'',sharedDriveId:'',sourceMode:'my'};
}
function archiveJsonFileName(snapshot={}){
  const raw=`${snapshot.title||snapshot.destination||'Viaje'} ${snapshot.startDate||''} ${snapshot.endDate||''}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._ -]+/g,'').trim().replace(/\s+/g,'_').slice(0,90)||'Viaje';
  return `${raw}_${snapshot.id||Date.now()}.json`;
}
function archiveReferenceFromSnapshot(snapshot={},uploaded={},folder={}){
  const flights=snapshot.flights||[],stats=snapshot.budget?.stats||{},rental=snapshot.rental||{},lodging=snapshot.lodging||{};
  return {
    id:snapshot.id,title:snapshot.title,archivedAt:snapshot.archivedAt,destination:snapshot.destination||'',year:snapshot.year||'',people:snapshot.people||1,
    departureDateTime:snapshot.departureDateTime||'',returnDateTime:snapshot.returnDateTime||'',startDate:snapshot.startDate||'',endDate:snapshot.endDate||'',
    budget:{stats:clone(stats)},purchaseTotals:clone(snapshot.purchaseTotals||{}),
    summary:{budgetStats:clone(stats),purchaseReal:num(snapshot.purchaseTotals?.real),lodging:{name:lodging.name||''},flightCount:flights.length,firstAirline:flights[0]?.airline||'',rental:{model:rental.model||''},cordialHotel:snapshot.cordial?.hotel||''},
    driveArchive:{fileId:String(uploaded.driveFileId||uploaded.id||''),fileName:String(uploaded.label||''),folderId:String(folder.id||uploaded.parentId||''),folderName:String(folder.name||''),mimeType:'application/json',size:num(uploaded.size),url:String(uploaded.driveUrl||uploaded.url||''),formatVersion:1},
    archiveVersion:4
  };
}
async function uploadHistorySnapshotToDrive(snapshot={},folder={}){
  if(!folder?.id)throw new Error('Elige primero la carpeta de Google Drive para el Histórico.');
  const payload={format:'mfe-viajes-history',formatVersion:1,createdAt:new Date().toISOString(),snapshot};
  const fileName=archiveJsonFileName(snapshot);
  const file=new File([JSON.stringify(payload)],fileName,{type:'application/json'});
  return uploadBlobToDrive(file,{name:fileName,parentId:folder.id,originalName:fileName,errorLabel:'archivo histórico'});
}
async function loadHistorySnapshotFromDrive(reference={}, {force=false}={}){
  if(!reference?.driveArchive?.fileId)return reference;
  const id=String(reference.id||reference.driveArchive.fileId),cached=state.historyArchiveCache.get(id);
  if(cached&&!force)return cached;
  const fileId=String(reference.driveArchive.fileId);
  const response=await authorizedDriveFetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`,{cache:'no-store'});
  if(!response.ok){let detail='';try{detail=(await response.json())?.error?.message||'';}catch{}throw new Error(`No se pudo leer el Histórico desde Drive (HTTP ${response.status})${detail?`: ${detail}`:''}.`);}
  const text=await response.text();let parsed;try{parsed=JSON.parse(text);}catch{throw new Error('El archivo histórico de Drive no contiene un JSON válido.');}
  const snapshot=parsed?.format==='mfe-viajes-history'?parsed.snapshot:parsed?.snapshot||parsed;
  if(!snapshot||typeof snapshot!=='object')throw new Error('El archivo histórico de Drive no contiene un viaje válido.');
  if(reference.id&&snapshot.id&&String(reference.id)!==String(snapshot.id))throw new Error('El archivo de Drive no corresponde con esta ficha del Histórico.');
  state.historyArchiveCache.set(id,snapshot);
  return snapshot;
}
async function readHistorySnapshotSelection(selected={}){
  const fileId=String(selected.driveFileId||selected.id||'').trim();if(!fileId)throw new Error('Google Drive no ha devuelto el identificador del JSON.');
  const [contentResponse,metaResponse]=await Promise.all([
    authorizedDriveFetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`,{cache:'no-store'}),
    authorizedDriveFetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?fields=id,name,mimeType,parents,size,webViewLink&supportsAllDrives=true`,{cache:'no-store'})
  ]);
  if(!contentResponse.ok)throw new Error(`No se pudo leer el JSON de Drive (HTTP ${contentResponse.status}).`);
  const text=await contentResponse.text();let parsed;try{parsed=JSON.parse(text);}catch{throw new Error('El archivo seleccionado no contiene un JSON válido.');}
  const snapshot=parsed?.format==='mfe-viajes-history'?parsed.snapshot:parsed?.snapshot||parsed;
  if(!snapshot||typeof snapshot!=='object')throw new Error('El JSON no contiene un snapshot de MFE Viajes.');
  if(!snapshot.id)snapshot.id=uid('trip-archive-import');
  if(!snapshot.title)snapshot.title=archiveTripTitle(snapshot);
  if(!snapshot.startDate&&snapshot.departureDateTime)snapshot.startDate=String(snapshot.departureDateTime).slice(0,10);
  if(!snapshot.endDate&&snapshot.returnDateTime)snapshot.endDate=String(snapshot.returnDateTime).slice(0,10);
  const stats=snapshot.budget?.stats||{};if(!Object.prototype.hasOwnProperty.call(stats,'total')||!Number.isFinite(Number(stats.total)))throw new Error('El JSON no contiene un total de presupuesto válido.');
  let meta={};if(metaResponse.ok){try{meta=await metaResponse.json();}catch{}}
  return {snapshot,meta:{id:fileId,name:meta.name||selected.label||'Histórico.json',mimeType:meta.mimeType||selected.mimeType||'application/json',parents:Array.isArray(meta.parents)?meta.parents:[],size:num(meta.size),webViewLink:meta.webViewLink||selected.driveUrl||selected.url||`https://drive.google.com/file/d/${fileId}/view`}};
}
async function importHistoryArchiveFromDrive(){
  if(!canEdit())return toast('Desbloquea la edición para importar un viaje al Histórico.','error');
  try{
    const selected=(await selectFromDrive({multiple:false,mimeTypes:'application/json',includeToken:false,sharedDrives:false,title:'Importar viaje histórico · JSON de Google Drive'}))[0];if(!selected)return;
    toast('Leyendo viaje histórico desde Google Drive…');
    const {snapshot,meta}=await readHistorySnapshotSelection(selected);
    state.data.history=state.data.history||{archives:[]};state.data.history.archives=Array.isArray(state.data.history.archives)?state.data.history.archives:[];
    if(state.data.history.archives.some(item=>String(item.id)===String(snapshot.id)))return toast('Ese viaje ya está añadido al Histórico.','error');
    const configured=archiveDriveFolder(),parentId=String(meta.parents?.[0]||'');
    const folder={id:parentId,name:configured.id===parentId?configured.name:'Google Drive'};
    const uploaded={driveFileId:meta.id,id:meta.id,label:meta.name,driveUrl:meta.webViewLink,url:meta.webViewLink,size:meta.size,parentId};
    const reference=archiveReferenceFromSnapshot(snapshot,uploaded,folder);
    if(snapshot.appearance)reference.appearance=clone(snapshot.appearance);
    state.data.history.archives.unshift(reference);
    await state.provider.saveSection('history',state.data.history);
    state.historyArchiveCache.set(String(snapshot.id),snapshot);render();toast(`${snapshot.title||'Viaje'} añadido al Histórico.`);
  }catch(error){toast(`No se pudo importar el Histórico: ${error.message}`,'error');}
}
function renderHistoryArchiveDetailModal(snapshot={}){
  const stats=snapshot.budget?.stats||{},dates=snapshot.startDate&&snapshot.endDate?`${formatDate(snapshot.startDate,{day:'2-digit',month:'short',year:'numeric'})} – ${formatDate(snapshot.endDate,{day:'2-digit',month:'short',year:'numeric'})}`:'Fechas no indicadas';
  openModal(`<div class="modal-head history-archive-modal-head"><div><span class="header-kicker">VIAJE ARCHIVADO</span><h3>${esc(snapshot.title||'Viaje')}</h3><small>${esc(dates)} · Archivado ${esc(formatDate(snapshot.archivedAt,{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}))}</small></div><button class="close-btn" data-close-modal>×</button></div><div class="history-archive-detail"><section class="history-archive-hero"><div><small>Gasto real final</small><strong>${formatMoney(stats.total||0)}</strong><span>Todo pagado</span></div><div><small>Compra real</small><strong>${formatMoney(snapshot.purchaseTotals?.real||0)}</strong><span>${snapshot.people||1} viajero${snapshot.people===1?'':'s'}</span></div></section><section class="history-detail-block"><div class="history-detail-block-head"><h4>💶 Presupuesto convertido a gasto real</h4><strong>${formatMoney(stats.total||0)}</strong></div>${archivedBudgetMarkup(snapshot)}</section><section class="history-detail-block"><div class="history-detail-block-head"><h4>🧾 Compras y gastos reales</h4><strong>${formatMoney(snapshot.purchaseTotals?.real||0)}</strong></div>${archivedPurchaseDetailMarkup(snapshot)}</section><section class="history-detail-block"><div class="history-detail-block-head"><h4>🏨 Alojamiento</h4></div>${archivedLodgingMarkup(snapshot)}</section>${snapshot.stages?.enabled?`<section class="history-detail-block"><div class="history-detail-block-head"><h4>🏝️ Etapas del viaje</h4></div><div class="history-archive-logistic-grid">${(snapshot.stages.items||[]).map((stage,i)=>`<article><span class="history-archive-icon">🏝️</span><div><strong>${esc(stageTitle(stage,i))}</strong><p>${esc([stage.start,stage.end].filter(Boolean).join(' → '))}</p><p>🏨 ${esc(i===0?(snapshot.lodging?.name||'Alojamiento'):(stage.hotel?.name||'Alojamiento pendiente'))}</p><p>🚗 ${esc(i===0?(snapshot.rental?.model||snapshot.rental?.group||'Coche'):(stage.car?.model||stage.car?.group||'Coche pendiente'))}</p><p>🛒 ${formatMoney(sum((snapshot.purchases?.records||[]).filter(r=>(r.stageId||'week-1')===stage.id).map(r=>r.amount)))}</p></div></article>`).join('')}</div></section>`:''}<section class="history-detail-block"><div class="history-detail-block-head"><h4>✈️ Vuelos</h4></div>${archivedFlightsMarkup(snapshot)}</section>${(snapshot.buses||[]).length?`<section class="history-detail-block"><div class="history-detail-block-head"><h4>🚌 Autobuses</h4></div>${archivedBusesMarkup(snapshot)}</section>`:''}<section class="history-detail-block"><div class="history-detail-block-head"><h4>🚗 Coche de alquiler</h4></div>${archivedRentalMarkup(snapshot)}</section><section class="history-detail-block history-tracker-snapshot"><div class="history-detail-block-head"><h4>📡 Seguimientos archivados</h4></div><div class="history-archive-summary-grid"><div><small>AutoReisen</small><strong>${formatMoney(num(snapshot.rental?.currentPrice||snapshot.rental?.reservedPrice))}</strong></div><div><small>Cordial</small><strong>${formatMoney(num(snapshot.cordial?.currentPrice||snapshot.cordial?.reservedPrice))}</strong></div><div><small>Vueling</small><strong>${formatMoney(num(snapshot.vueling?.currentPrice||snapshot.vueling?.reservedPrice))}</strong></div></div></section><div class="history-archive-actions">${snapshot.readOnlyArchive===true?'':`<button type="button" class="btn secondary history-undo-button" data-undo-history-archive="${esc(snapshot.id)}">🔐 Deshacer archivo</button>`}<button type="button" class="btn secondary" data-close-modal>Cerrar</button></div><p class="help-text history-undo-help">${snapshot.readOnlyArchive===true?'Histórico importado en modo solo lectura. El detalle se lee del archivo guardado en Google Drive.':'El detalle se lee del archivo guardado en Google Drive. Deshacer requiere la biometría/verificación segura de este dispositivo y solo se permite si no hay datos de otro viaje activo.'}</p></div>`,true);
  $('[data-undo-history-archive]',els.modal)?.addEventListener('click',()=>openUndoArchiveConfirm(snapshot.id));
}
async function openHistoryArchiveDetail(id){
  const reference=historyArchiveById(id);if(!reference)return toast('No se ha encontrado el viaje archivado.','error');
  if(reference.driveArchive?.fileId)openModal(`<div class="modal-head"><h3>${esc(reference.title||'Viaje archivado')}</h3><button class="close-btn" data-close-modal>×</button></div><div class="modal-body"><div class="archive-drive-loading">☁ Cargando el Histórico desde Google Drive…</div></div>`,true);
  try{const snapshot=await loadHistorySnapshotFromDrive(reference);renderHistoryArchiveDetailModal(snapshot);}
  catch(error){openModal(`<div class="modal-head"><h3>Histórico no disponible</h3><button class="close-btn" data-close-modal>×</button></div><div class="modal-body"><p>No se ha podido abrir el archivo guardado en Google Drive.</p><p class="help-text">${esc(error.message)}</p>${reference.driveArchive?.url?`<div class="page-actions"><a class="btn secondary" href="${esc(reference.driveArchive.url)}" target="_blank" rel="noopener">↗ Abrir archivo en Drive</a></div>`:''}</div>`,true);}
}
function currentTripHasRestorableData(){
  const s=state.data.settings||{},p=state.data.purchases||{},groups=state.data.budget?.groups||[],km=state.data.budget?.carKm||{};
  const hasCarKm=(km.initial!==''&&km.initial!==null&&km.initial!==undefined)||(km.final!==''&&km.final!==null&&km.final!==undefined);
  // Vuelos/alojamiento/coche pueden permanecer como plantilla tras archivar. Solo consideramos
  // que hay un nuevo viaje activo cuando ya existen fechas/año o datos económicos nuevos.
  return Boolean(String(s.year||'').trim()||String(s.departureDateTime||'').trim()||String(s.returnDateTime||'').trim()||groups.some(g=>(g.items||[]).length)||hasCarKm||(p.records||[]).length||(p.ticketItems||[]).length||(p.otherExpenses||[]).length||(p.extras||[]).length);
}
function archiveFallbackRestorePayload(snapshot={}){
  return {settings:{destination:snapshot.destination||'',year:snapshot.year||'',people:snapshot.people||1,departureDateTime:snapshot.departureDateTime||'',returnDateTime:snapshot.returnDateTime||'',countdownEndDateTime:''},budget:{...(state.data.budget||{}),groups:clone(snapshot.budget?.groups||[]),carKm:clone(snapshot.budget?.carKm||snapshot.carKm||{initial:'',final:''})},purchases:clone(snapshot.purchases||{}),stages:clone(snapshot.stages||state.data.stages||{}),cover:{flights:clone(snapshot.flights||[]),buses:clone(snapshot.buses||[]),lodging:clone(snapshot.lodging||{}),documents:clone(snapshot.coverDocuments||[])},trackers:{autoreisen:pickArchiveFields(snapshot.rental||{},ARCHIVE_TRACKER_FIELDS.autoreisen),cordial:pickArchiveFields(snapshot.cordial||{},ARCHIVE_TRACKER_FIELDS.cordial),vueling:pickArchiveFields(snapshot.vueling||{},ARCHIVE_TRACKER_FIELDS.vueling)}};
}
function mergeArchivedDocumentsIntoCover(documents=[]){
  const archived=new Map((documents||[]).map(d=>[String(d?.id||''),clone(d)]));
  const current=state.data.cover?.documents||[];const seen=new Set();
  state.data.cover.documents=current.map(doc=>{const id=String(doc?.id||'');if(archived.has(id)){seen.add(id);return archived.get(id);}return doc;});
  for(const [id,doc] of archived.entries())if(!seen.has(id))state.data.cover.documents.push(doc);
}
function applyTrackerRestoreFields(id,values={}){const target=state.data.trackers?.[id];if(!target)return;for(const key of ARCHIVE_TRACKER_FIELDS[id]||[])if(Object.prototype.hasOwnProperty.call(values,key))target[key]=clone(values[key]);}
function applyArchiveRestorePayload(snapshot={}){
  const payload=snapshot.restorePayload||archiveFallbackRestorePayload(snapshot),sp=payload.settings||{};
  for(const key of ['destination','year','people','departureDateTime','returnDateTime','countdownEndDateTime'])if(Object.prototype.hasOwnProperty.call(sp,key))state.data.settings[key]=clone(sp[key]);
  if(payload.budget)state.data.budget=clone(payload.budget);
  if(payload.purchases)state.data.purchases=clone(payload.purchases);
  if(payload.stages)state.data.stages=clone(payload.stages);
  if(payload.cover){state.data.cover.flights=clone(payload.cover.flights||[]);state.data.cover.buses=clone(payload.cover.buses||[]);state.data.cover.lodging=clone(payload.cover.lodging||{});mergeArchivedDocumentsIntoCover(payload.cover.documents||[]);}
  for(const id of ['autoreisen','cordial','vueling'])applyTrackerRestoreFields(id,payload.trackers?.[id]||{});
}
async function openUndoArchiveConfirm(id){
  const reference=historyArchiveById(id);if(!reference)return;
  if(currentTripHasRestorableData())return openModal(`<div class="modal-head"><h3>No se puede deshacer todavía</h3><button class="close-btn" data-close-modal>×</button></div><div class="modal-body"><p>Hay datos de otro viaje en la zona activa. Para evitar sobrescribirlos, primero archiva ese viaje o deja vacíos los campos que forman parte del Histórico.</p><div class="page-actions"><button class="btn secondary" data-close-modal>Cerrar</button></div></div>`,true);
  let snapshot;try{snapshot=await loadHistorySnapshotFromDrive(reference);}catch(error){return toast(`No se puede deshacer sin leer el archivo de Drive: ${error.message}`,'error');}
  openModal(`<div class="modal-head"><h3>Deshacer archivo</h3><button class="close-btn" data-close-modal>×</button></div><div class="modal-body"><div class="archive-confirm-summary"><strong>${esc(snapshot.title||'Viaje')}</strong><span>Se restaurará como viaje activo y desaparecerá de Histórico.</span></div><div class="archive-check-list"><div>🔐 Requiere biometría/verificación del dispositivo</div><div>✓ Restaurará presupuesto, compras, vuelos, alojamiento y coche</div><div>✓ Solo modifica los mismos campos que fueron archivados</div><div>✓ No sobrescribe otro viaje activo</div></div><p class="help-text">El JSON original de Google Drive se conserva como copia de seguridad aunque deshagas el archivo.</p><div class="page-actions"><button class="btn secondary" data-close-modal>Cancelar</button><button class="btn primary" data-confirm-undo-history="${esc(snapshot.id)}">🔐 Deshacer archivo</button></div></div>`,true);
  $('[data-confirm-undo-history]',els.modal)?.addEventListener('click',()=>undoHistoryArchive(snapshot.id));
}
async function undoHistoryArchive(id){
  const reference=historyArchiveById(id);if(!reference)return toast('No se ha encontrado el archivo.','error');
  if(currentTripHasRestorableData())return toast('Hay datos de otro viaje activo. No se sobrescribirá.','error');
  if(!deviceAuthConfigured())return toast('Activa primero la biometría/verificación del dispositivo en Configuración → Seguridad.','error');
  const button=$('[data-confirm-undo-history]',els.modal);if(button){button.disabled=true;button.textContent='Verificando…';}
  let snapshot;try{snapshot=await loadHistorySnapshotFromDrive(reference);}catch(error){if(button){button.disabled=false;button.textContent='🔐 Deshacer archivo';}return toast(`No se pudo leer el archivo histórico de Drive: ${error.message}`,'error');}
  try{const ok=await authenticateWithDevice();if(!ok)throw new Error('No se pudo verificar el dispositivo.');}
  catch(error){if(button){button.disabled=false;button.textContent='🔐 Deshacer archivo';}return toast(deviceAuthErrorMessage(error),'error');}
  const memoryBackup=clone({settings:state.data.settings,budget:state.data.budget,purchases:state.data.purchases,stages:state.data.stages,cover:state.data.cover,trackers:state.data.trackers,history:state.data.history});
  try{
    applyArchiveRestorePayload(snapshot);
    await Promise.all(['settings','budget','purchases','stages','cover','trackers'].map(section=>state.provider.saveSection(section,state.data[section])));
    state.data.history.archives=(state.data.history.archives||[]).filter(item=>String(item.id)!==String(snapshot.id));
    await state.provider.saveSection('history',state.data.history);
    state.historyArchiveCache.delete(String(snapshot.id));
    closeModal();render();toast('Archivo deshecho. El viaje vuelve a estar activo; la copia JSON permanece en Drive.');
  }catch(error){Object.assign(state.data,{settings:memoryBackup.settings,budget:memoryBackup.budget,purchases:memoryBackup.purchases,stages:memoryBackup.stages,cover:memoryBackup.cover,trackers:memoryBackup.trackers,history:memoryBackup.history});render();toast(`No se pudo deshacer el archivo: ${error.message}`,'error');}
}
async function recoverReusableTripTemplateFromLatestArchive(){
  if(!canEdit())return toast('Desbloquea la edición para recuperar la plantilla.','error');
  const reference=latestHistoryArchiveReference();if(!reference)return toast('No hay ningún viaje archivado del que recuperar la configuración.','error');
  try{
    toast(`Recuperando configuración de ${reference.title||'último viaje'}…`);
    const snapshot=await loadHistorySnapshotFromDrive(reference);
    applyReusableTripTemplate(snapshot);
    await Promise.all(['settings','cover','trackers','stages'].map(section=>state.provider.saveSection(section,state.data[section])));
    render();toast(`Plantilla recuperada de ${snapshot.title||reference.title||'último viaje'}. Solo tienes que cambiar fechas, precios o lo que necesites.`);
  }catch(error){toast(`No se pudo recuperar la plantilla: ${error.message}`,'error');}
}
function fullResetFlights(){
  state.data.cover.flights=[];
  resetTrackerForNewTrip('vueling');
}
function fullResetLodging(){
  state.data.cover.lodging={...(state.data.cover.lodging||{}),name:'',checkIn:'',checkOut:'',website:'',mapsUrl:'',imageUrl:'',address:'',googleReviewsUrl:'',tripadvisorReviewsUrl:'',bookingReviewsUrl:'',guestGuideUrl:''};
  resetTrackerForNewTrip('cordial');
}
function promptProtectedTripDataReset(kind){
  const isFlights=kind==='flights',label=isFlights?'vuelos y seguimiento Vueling':'alojamiento y seguimiento Cordial';
  openForm({title:isFlights?'Resetear vuelos':'Resetear alojamiento',submitText:'Resetear',submitClass:'danger',fields:[{name:'pin',label:'PIN de edición',type:'password',required:true,full:true,help:`Acción protegida: se vaciarán los datos de ${label}. El Histórico no se modifica.`,warning:true}],onSubmit:async({pin})=>{
    await verifyEditPin(pin);
    if(isFlights)fullResetFlights();else fullResetLodging();
    await Promise.all([state.provider.saveSection('cover',state.data.cover),state.provider.saveSection('trackers',state.data.trackers)]);
    render();toast(isFlights?'Vuelos y seguimiento Vueling reseteados.':'Alojamiento y seguimiento Cordial reseteados.');
  }});
}

function openArchiveTripConfirm(){
  const snap=buildTripArchiveSnapshot(),folder=archiveDriveFolder();
  openModal(`<div class="modal-head"><h3>Archivar viaje</h3><button class="icon-btn" data-close-modal>×</button></div><div class="archive-confirm-body"><p class="archive-confirm-lead">Se guardará una copia completa en Google Drive. Después se vaciarán los gastos del viaje y se conservarán hotel, vuelos, coche y seguimientos como plantilla para el siguiente.</p><div class="archive-confirm-summary"><strong>${esc(snap.title)}</strong><span>${formatMoney(snap.budget.stats.total)} · todo se consolidará como gasto real pagado</span></div><div class="archive-drive-target"><div><small>Carpeta del Histórico en Google Drive</small><strong data-history-drive-folder-label>${esc(folder.name||'Sin seleccionar')}</strong><span>${folder.id?'Se recordará y sincronizará entre dispositivos.':'Créala en Drive y selecciónala una sola vez.'}</span></div><button type="button" class="btn secondary" data-history-drive-folder>📁 ${folder.id?'Cambiar':'Elegir carpeta'}</button></div><div class="archive-check-list"><div>☁ El snapshot completo se guardará como un único JSON en Drive</div><div>✓ Fechas, alojamiento, vuelos, coche y kilómetros registrados</div><div>✓ Presupuesto completo convertido a gasto real</div><div>✓ Compra real, otros gastos y productos de tickets</div><div>✓ Datos principales de AutoReisen, Cordial y Vueling</div><div>↻ Firebase solo conservará una ficha ligera y el ID del archivo</div><div>♻ Hotel, vuelos, coche y configuración de seguimientos permanecerán preparados para reutilizarse</div></div><p class="help-text">Los gastos, kilómetros y documentos del viaje se limpian solo después de que Drive y la ficha de Histórico hayan confirmado el guardado. La configuración reutilizable no se borra.</p><div class="page-actions"><button type="button" class="btn secondary" data-close-modal>Cancelar</button><button type="button" class="btn primary archive-trip-action" data-confirm-archive-trip ${folder.id?'':'disabled'}>🗂️ Archivar viaje</button></div></div>`,true);
  const updateFolderUi=()=>{const f=archiveDriveFolder(),label=$('[data-history-drive-folder-label]',els.modal),confirm=$('[data-confirm-archive-trip]',els.modal),pick=$('[data-history-drive-folder]',els.modal);if(label)label.textContent=f.name||'Sin seleccionar';if(confirm)confirm.disabled=!f.id;if(pick)pick.textContent=`📁 ${f.id?'Cambiar':'Elegir carpeta'}`;};
  $('[data-history-drive-folder]',els.modal)?.addEventListener('click',async()=>{try{const chosen=await selectDriveFolder();if(!chosen)return;state.data.settings.historyDriveFolder={id:chosen.id,name:chosen.name,sharedDriveId:chosen.sharedDriveId||'',sourceMode:chosen.sourceMode||'my'};await state.provider.saveSection('settings',state.data.settings);updateFolderUi();toast(`Carpeta del Histórico: ${chosen.name}`);}catch(error){toast(`No se pudo seleccionar la carpeta: ${error.message}`,'error');}});
  $('[data-confirm-archive-trip]',els.modal)?.addEventListener('click',archiveCurrentTrip);
}
async function archiveCurrentTrip(){
  if(!canEdit()){toast('Desbloquea la edición para archivar el viaje.','error');return;}
  const folder=archiveDriveFolder();if(!folder.id)return toast('Elige primero la carpeta de Google Drive para guardar el Histórico.','error');
  const button=$('[data-confirm-archive-trip]',els.modal);if(button){button.disabled=true;button.textContent='Subiendo a Drive…';}
  state.data.budget.conceptIconMemory=mergedBudgetConceptIconMemory(state.data);
  const snapshot=buildTripArchiveSnapshot();state.data.history=state.data.history||{archives:[]};state.data.history.archives=Array.isArray(state.data.history.archives)?state.data.history.archives:[];
  let uploaded=null,reference=null;
  try{
    uploaded=await uploadHistorySnapshotToDrive(snapshot,folder);
    if(button)button.textContent='Guardando ficha…';
    reference=archiveReferenceFromSnapshot(snapshot,uploaded,folder);
    state.data.history.archives.unshift(reference);
    await state.provider.saveSection('history',state.data.history);
    state.historyArchiveCache.set(String(snapshot.id),snapshot);
  }catch(error){
    if(reference)state.data.history.archives=state.data.history.archives.filter(x=>x.id!==snapshot.id);
    if(uploaded?.driveFileId){try{await deleteDriveFileById(uploaded.driveFileId);}catch{}}
    if(button){button.disabled=false;button.textContent='🗂️ Archivar viaje';}
    toast(`No se ha archivado: ${error.message}`,'error');return;
  }
  resetCurrentTripAfterArchive();
  try{
    await Promise.all(['settings','budget','purchases','cover','trackers'].map(section=>state.provider.saveSection(section,state.data[section])));
    closeModal();render();toast(`Viaje archivado en Drive · ${folder.name}. Configuración reutilizable conservada para el próximo viaje.`);
  }catch(error){closeModal();render();toast('El viaje está archivado en Drive, pero algún campo activo no pudo reiniciarse. El histórico está a salvo.','error');console.error(error);}
}
function renderHistory(){
  const archives=sortedHistoryArchives();
  const actions=canEdit()?'<div class="page-actions history-page-actions"><button type="button" class="btn secondary" data-import-history-drive>☁ Importar JSON</button><button type="button" class="btn primary history-archive-button" data-archive-trip>🗂️ Archivar viaje</button></div>':'';
  return `${lockedBanner()}${pageHead('Histórico','Viajes finalizados y gastos reales',actions)}${historyCurrentTripPreview()}<section class="history-archive-list"><div class="history-list-head"><div><span class="header-kicker">VIAJES ARCHIVADOS</span><h3>Tu histórico</h3></div><strong>${archives.length} viaje${archives.length===1?'':'s'}</strong></div>${archives.length?archives.map(historyArchiveCard).join(''):'<div class="empty card history-empty">Todavía no has archivado ningún viaje.</div>'}</section>`;
}
