    kg:VUELING_BAG_WEIGHTS.includes(num(item?.kg))?num(item.kg):25,
    passenger:Math.max(1,Math.min(seated,num(item?.passenger)||1)),
    outbound:item?.outbound!==false,
    return:item?.return!==false
